from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCrossoverOptions(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self._minute_bars = {}
        self._bar_date = None

        self._closes = []
        self._previous_fast = None
        self._previous_slow = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._assignment_liquidation_submitted = False

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        if self._held_symbol is not None:
            self._process_expiration_and_exits(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        current_date = end_time.date()

        if self._bar_date != current_date:
            self._minute_bars.clear()
            self._bar_date = current_date

        hour = end_time.hour
        minute = end_time.minute

        if hour < 9 or (hour == 9 and minute < 31):
            return
        if hour > 16 or (hour == 16 and minute > 0):
            return

        bucket_end_minute = ((minute + 4) // 5) * 5
        if bucket_end_minute > 60:
            return

        bucket_end = end_time.replace(
            minute=0 if bucket_end_minute == 60 else bucket_end_minute,
            second=0,
            microsecond=0
        )
        if bucket_end_minute == 60:
            bucket_end += timedelta(hours=1)

        bucket = self._minute_bars.setdefault(bucket_end, {})
        bucket[end_time] = bar

        if minute % 5 != 0:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if any(expected not in bucket for expected in expected_times):
            self._minute_bars.pop(bucket_end, None)
            return

        minute_bars = [bucket[expected] for expected in expected_times]
        self._minute_bars.pop(bucket_end, None)

        five_minute_close = minute_bars[-1].Close
        self._update_moving_averages(five_minute_close, bucket_end, slice)

    def _update_moving_averages(self, close, bar_end, slice: Slice):
        if len(self._closes) >= 20:
            self._previous_fast = sum(self._closes[-5:]) / 5.0
            self._previous_slow = sum(self._closes[-20:]) / 20.0

        self._closes.append(float(close))
        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        current_fast = sum(self._closes[-5:]) / 5.0
        current_slow = sum(self._closes[-20:]) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and current_fast > current_slow
        )

        if bullish_cross and self._is_eligible_entry_time(bar_end):
            self._try_enter(slice)

    def _is_eligible_entry_time(self, time):
        minutes = time.hour * 60 + time.minute
        return 9 * 60 + 45 <= minutes <= 14 * 60 + 30

    def _try_enter(self, slice: Slice):
        if self._entry_order_open() or self._option_holding_exists():
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped option selection: unavailable SPY price.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped option selection: no option chain in Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped option selection: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped option selection: no qualifying contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self._held_symbol = selected.Symbol
        self._entry_price = None
        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Submitted entry for {0}, expiry {1}, strike {2}.".format(
                selected.Symbol, selected.Expiry.date(), selected.Strike
            )
        )

    def _process_expiration_and_exits(self, slice: Slice):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        expiry = self.Securities[self._held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry:
            self._submit_exit("expiration processing")
            return

        preceding_trading_day = self._preceding_trading_day(expiry)
        current_minutes = self.Time.hour * 60 + self.Time.minute

        if (
            current_date == preceding_trading_day
            and current_minutes >= 15 * 60 + 45
        ):
            self._submit_exit("expiration time stop")
            return

        if self._entry_price is None or self._exit_order_open():
            return

        bid, ask = self._current_option_quote(slice, self._held_symbol)
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _current_option_quote(self, slice: Slice, symbol):
        quote = slice.QuoteBars.get(symbol)
        if quote is not None:
            bid = quote.Bid.Close if quote.Bid is not None else None
            ask = quote.Ask.Close if quote.Ask is not None else None
            if bid is not None and ask is not None:
                return bid, ask

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract.BidPrice, contract.AskPrice

        return None, None

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_order_open():
            return

        if self._entry_ticket is not None and self._entry_order_open():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        if self._entry_ticket is not None:
            self._entry_ticket.Cancel("Exit condition reached.")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity
        )
        self.Debug(
            "Submitted exit for {0}: {1}.".format(self._held_symbol, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled for {0} at {1}.".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.Debug("Entry order did not fill.")
                self._entry_ticket = None
                self._held_symbol = None
                self._entry_price = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled for {0}.".format(order_event.Symbol))
            self._exit_ticket = None
            self._entry_ticket = None
            self._held_symbol = None
            self._entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.Debug("Unexpected option exercise or assignment detected.")
        self._liquidate_unexpected_equity()

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Invested:
            self._liquidate_unexpected_equity()

    def _liquidate_unexpected_equity(self):
        if self._assignment_liquidation_submitted:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Liquidating unexpected SPY equity position.")
            self.MarketOrder(self.spy, -quantity)
            self._assignment_liquidation_submitted = True

    def _entry_order_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def _exit_order_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def _option_holding_exists(self):
        return (
            self._held_symbol is not None
            and self.Portfolio[self._held_symbol].Invested
        )

    def _preceding_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

