from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(0), timedelta(days=730))
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.expiration_blocked_date = None
        self.spy_cleanup_submitted = False

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self.ProcessExpiration
        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None and self.entry_price is not None:
            self.EvaluateProfitTarget(slice)
            self.EvaluateTimeStop()

        if slice.Bars.ContainsKey(self.spy):
            self.ConsumeMinuteBar(slice.Bars[self.spy])

    def ConsumeMinuteBar(self, bar: TradeBar):
        minute = bar.Time.replace(second=0, microsecond=0)
        local_time = minute.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        bucket_minute = minute.minute - (minute.minute % 5)
        bucket_start = minute.replace(minute=bucket_minute)

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self.FinalizeBucket()
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[minute] = bar

    def FinalizeBucket(self):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(minute in self.bucket_bars for minute in expected):
            close = self.bucket_bars[expected[-1]].Close
            end_time = self.bucket_start + timedelta(minutes=5)
            self.OnFiveMinuteBar(end_time, close)

        self.bucket_bars = {}

    def OnFiveMinuteBar(self, end_time, close):
        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_crossover:
            return

        end_clock = end_time.time()
        eligible = time(9, 45) <= end_clock <= time(14, 30)

        if not eligible:
            return

        current_date = end_time.date()

        if self.expiration_blocked_date == current_date:
            return

        if self.held_symbol is not None or self.IsEntryOrderOpen():
            return

        self.TryEnter(slice_=self.CurrentSlice, current_price=float(close), current_date=current_date)

    def TryEnter(self, slice_, current_price, current_date):
        if not slice_.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice_.OptionChains[self.option_symbol]
        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        strike_floor = current_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
