from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishOptionStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.minute_closes = {}
        self.last_session_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.pre_expiration_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        if self.last_session_date != today:
            self.minute_closes.clear()
            self.last_session_date = today
            self.no_entry_today = False

        self._liquidate_unexpected_spy_position()
        self._process_option_expiration(now)

        if self.held_option is not None:
            self._evaluate_exit(slice, now)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        crossover = False
        completed_bar_time = None
        current_spy_price = None

        if spy_bar is not None:
            current_spy_price = float(spy_bar.Close)
            minute_key = now - timedelta(minutes=1)

            if self._is_regular_session_minute(minute_key):
                self.minute_closes[minute_key] = float(spy_bar.Close)

        if now.minute % 5 == 0 and now.second == 0:
            completed_bar_time = now
            crossover = self._complete_five_minute_bar(now)

        if (
            crossover
            and completed_bar_time.time() >= time(9, 45)
            and completed_bar_time.time() <= time(14, 30)
            and current_spy_price is not None
        ):
            self._try_enter(slice, today, current_spy_price)

    def _complete_five_minute_bar(self, end_time):
        start_time = end_time - timedelta(minutes=5)
        expected = [
            start_time + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.minute_closes for t in expected):
            for t in expected:
                self.minute_closes.pop(t, None)
            return False

        close = self.minute_closes[expected[-1]]
        for t in expected:
            self.minute_closes.pop(t, None)

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return False

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        return (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

    def _try_enter(self, slice, algorithm_date, spy_price):
        if self.no_entry_today:
            return

        if self.held_option is not None or self._entry_order_is_open():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiration = algorithm_date + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                expiration = contract.Expiry.date()
                if (
                    expiration >= minimum_expiration
                    and contract.Right == OptionRight.Call
                    and float(contract.Strike) >= spy_price * 1.01
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying option")
            return

        selected = sorted(
            contracts,
            key=lambda contract: (
                contract.Expiry.date(),
                float(contract.Strike),
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_exit(self, slice, now):
        if self.held_option is None or self.entry_price is None:
            return

        expiration_date = self.held_option.ID.Date.date()

        if (
            self.pre_expiration_date is not None
            and now.date() == self.pre_expiration_date
            and now.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_option_expiration(self, now):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()

        if now.date() >= expiration_date:
            self.no_entry_today = True
            self._submit_exit("expiration protection")
            self.Debug("Expiration protection: " + str(self.held_option))

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            ):
                return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _is_regular_session_minute(self, value):
        return (
            value.weekday() < 5
            and time(9, 30) <= value.time() < time(16, 0)
        )

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _liquidate_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity == 0:
            return

        self.Debug("Unexpected SPY equity position; liquidating")
        self.MarketOrder(self.spy.Symbol, -holding.Quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.FillQuantity == 0:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                )
            ):
                self.entry_ticket = None
                self.Debug("Entry skipped: order did not fill")

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
                and order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                )
            ):
                self.exit_ticket = None
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_option = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.pre_expiration_date = self._previous_trading_day(
                self.held_option.ID.Date.date()
            )

            if order_event.Status == OrderStatus.Filled:
                self.entry_ticket = None

            self.Debug(
                "Entry filled: " + str(self.held_option) +
                " @ " + str(self.entry_price)
            )
            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.pre_expiration_date = None
            return

        if (
            order_event.Symbol == self.spy.Symbol
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY exercise or assignment; liquidating")
            quantity = self.Portfolio[self.spy.Symbol].Quantity
            if quantity != 0:
                self.MarketOrder(self.spy.Symbol, -quantity)

