    def _complete_five_minute_bar(self, end_time):
        start_time = end_time - timedelta(minutes=5)
        expected = [
            start_time + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.minute_closes for t in expected):
            for t in expected:
                self.minute_closes.pop(t, None)
            return False

        close = self.minute_closes[expected[-1]]
        for t in expected:
            self.minute_closes.pop(t, None)

