from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCrossoverOptionAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )
        self.spy_option = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end_minute = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._evaluate_exit(slice)

        spy_bar = slice.Bars[self.spy] if self.spy in slice.Bars else None
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        t = self.Time
        if t.time() < time(9, 30) or t.time() > time(16, 0):
            return

        minute = t.hour * 60 + t.minute
        bucket_end = ((minute + 4) // 5) * 5
        bucket_date = t.date()

        if self.bucket_date != bucket_date or self.bucket_end_minute != bucket_end:
            self._finalize_bucket()

            self.bucket_date = bucket_date
            self.bucket_end_minute = bucket_end
            self.bucket_closes = {}

        self.bucket_closes[minute] = float(bar.Close)

        if minute == bucket_end:
            self._finalize_bucket()

    def _finalize_bucket(self):
        if self.bucket_date is None or self.bucket_end_minute is None:
            return

        expected = set(
            range(self.bucket_end_minute - 4, self.bucket_end_minute + 1)
        )

        if set(self.bucket_closes.keys()) == expected:
            close = self.bucket_closes[self.bucket_end_minute]
            bar_end = datetime(
                self.bucket_date.year,
                self.bucket_date.month,
                self.bucket_date.day,
                self.bucket_end_minute // 60,
                self.bucket_end_minute % 60
            )
            self._process_five_minute_close(close, bar_end)

        self.bucket_closes = {}

    def _process_five_minute_close(self, close: float, bar_end: datetime):
        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.closes.Add(close)

        if self.closes.Count < 20:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if (
            self.held_option is not None and
            self.Portfolio[self.held_option].Invested
        ):
            return

        if self.entry_ticket is not None and not self._ticket_finished(
            self.entry_ticket
        ):
            return

        self._enter_option(self._current_slice)

    def _enter_option(self, slice: Slice):
        if not hasattr(self, "_current_slice"):
            self._current_slice = slice
        else:
            self._current_slice = slice

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        chain = (
            slice.OptionChains[self.spy_option]
            if self.spy_option in slice.OptionChains
            else None
        )

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = float(slice.Bars[self.spy].Close) * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )
        contract = candidates[0]

        self.entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="Bullish crossover entry"
        )
        self.Debug(
            f"Entry submitted: {contract.Symbol} "
            f"expiration={selected_expiry} strike={contract.Strike}"
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.expiration_date is not None:
            if self.Time.date() >= self.expiration_date:
                self.no_entry_date = self.Time.date()
                self._submit_exit("Expiration protection")
                return

            if (
                self.time_stop_date == self.Time.date() and
                self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("Pre-expiration time stop")
                return

        if self.entry_price is None:
            return

        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self._ticket_finished(
            self.exit_ticket
        ):
            return

        if self.entry_ticket is not None and not self._ticket_finished(
            self.entry_ticket
        ):
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason} symbol={self.held_option}")

    def OnOrderEvent(self, order_event: OrderEvent):
        order_id = order_event.OrderId
        status = order_event.Status

        if (
            self.entry_ticket is not None and
            order_id == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.entry_price = float(order_event.FillPrice)

            if status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.expiration_date = self.held_option.ID.Date.date()

                candidate = self.expiration_date - timedelta(days=1)
                while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                    candidate
                ):
                    candidate -= timedelta(days=1)

                self.time_stop_date = candidate
                self.Debug(
                    f"Entry filled: {self.held_option} "
                    f"price={self.entry_price}"
                )

            elif status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_id == self.exit_ticket.OrderId and
            status == OrderStatus.Filled
        ):
            self.Debug(
                f"Exit filled: {self.exit_ticket.Symbol} "
                f"price={order_event.FillPrice}"
            )
            self.exit_ticket = None
            self.entry_ticket = None
            self.held_option = None
            self.entry_price = None
            self.expiration_date = None
            self.time_stop_date = None

        is_assignment = getattr(order_event, "IsAssignment", False)
        is_exercise = getattr(order_event, "IsExercise", False)

        if is_assignment or is_exercise:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment detected.")
            if self.Portfolio[self.spy].Invested:
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Liquidate unexpected SPY position"
                )

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Invested:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Liquidate unexpected SPY position"
            )

    @staticmethod
    def _ticket_finished(ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

