        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        bucket_start_minute = 30 + ((local_time.minute - 30) // 5) * 5
        bucket_start = local_time.replace(
            minute=bucket_start_minute,
            second=0,
            microsecond=0
        )
        bucket_key = bucket_start

        if self._bucket_key is not None and bucket_key != self._bucket_key:
            completed = self._complete_bucket()
            self._bucket_key = bucket_key
            self._bucket_bars = {local_time: minute_bar}

