            return None

        expected_times = [
            self._bucket_key + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._bucket_bars for t in expected_times):
            return None

        bars = [self._bucket_bars[t] for t in expected_times]
        close = bars[-1].Close
        bar_end = self._bucket_key + timedelta(minutes=5)
        return close, bar_end

    def _evaluate_crossover(self, close, bar_end, slice):
        if len(self._closes) >= 20:
            previous_fast = sum(self._closes[-5:]) / 5.0
            previous_slow = sum(self._closes[-20:]) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self._closes.append(float(close))
        if len(self._closes) > 20:
            self._closes.pop(0)

