            return

        quote = slice.BidAskBars[self._held_symbol]
        bid = float(quote.Bid)
        ask = float(quote.Ask)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if (
            self._entry_price is not None and
            midpoint >= 1.50 * self._entry_price
        ):
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_is_open():
            self._exit_ticket.Cancel("Replacing exit order")
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None and
            order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None
                self.Debug(
                    "Entry filled: " +
                    str(order_event.Symbol) +
                    " at " +
                    str(self._entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order did not fill.")
                self._entry_ticket = None

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._exit_ticket = None

        if order_event.OrderType == OrderType.OptionExercise:
            self._blocked_date = self.Time.date()
            self.Debug("Unexpected option exercise; liquidating SPY equity.")
            if self.Portfolio[self.spy.Symbol].Invested:
                self.Liquidate(self.spy.Symbol)

    def OnAssignmentOrderEvent(self, assignment_event):
        self._blocked_date = self.Time.date()
        self.Debug("Unexpected option assignment; liquidating SPY equity.")
        if self.Portfolio[self.spy.Symbol].Invested:
            self.Liquidate(self.spy.Symbol)

    def _option_position_exists(self):
        return (
            self._held_symbol is not None and
            self.Portfolio[self._held_symbol].Invested
        )

    def _entry_order_is_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_is_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

