            local_date.year, local_date.month, local_date.day, 9, 30
        )
        session_end = datetime(
            local_date.year, local_date.month, local_date.day, 16, 0
        )

        if start < session_start or start >= session_end:
            return None

        elapsed_minutes = int((start - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        completed = None

        if self.bucket_start is None:
            self.bucket_start = bucket_start
            self.bucket_date = local_date

        elif bucket_start != self.bucket_start:
            completed = self._complete_bucket()
            self.bucket_start = bucket_start
            self.bucket_date = local_date
            self.bucket_minutes = {}

        if local_date != self.bucket_date:
            self.bucket_start = bucket_start
            self.bucket_date = local_date
            self.bucket_minutes = {}

