from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=730))
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_start = None
        self.bucket_bars = []

        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_stop_date = None
        self.blocked_entry_date = None
        self.equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity(slice)
        self._handle_expiration()

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._process_minute_bar(bar, slice)

        self._evaluate_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        timestamp = self.Time.replace(second=0, microsecond=0)
        minute_of_day = timestamp.hour * 60 + timestamp.minute

        # Regular NYSE session only.
        if minute_of_day < 570 or minute_of_day >= 960:
            return

        bucket_number = (minute_of_day - 570) // 5
        bucket_start = timestamp.replace(
            hour=9, minute=30
        ) + timedelta(minutes=5 * bucket_number)

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._complete_bucket(slice)

            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(bar)

    def _complete_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        bucket_bars = self.bucket_bars
        bucket_start = self.bucket_start
        self.bucket_bars = []

        # Require all five minute bars. Missing data invalidates the interval.
        if len(bucket_bars) != 5:
            return

        expected_times = {
            bucket_start + timedelta(minutes=i) for i in range(5)
        }
        actual_times = {
            bar.Time.replace(second=0, microsecond=0) for bar in bucket_bars
        }

        if actual_times != expected_times:
            return

        close = bucket_bars[-1].Close
        if close <= 0:
            return

        self.closes.append(float(close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        bar_end = bucket_start + timedelta(minutes=5)
        eligible_time = (
            datetime.combine(bar_end.date(), bar_end.time()).time()
        )
        eligible = (
            datetime.strptime("09:45", "%H:%M").time()
            <= eligible_time
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_crossover and eligible:
            self._try_entry(slice, close)

    def _try_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._is_terminal(
            self.entry_ticket.Status
        ):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        candidates.sort(
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )

        self.Debug(
            "Entry submitted: {} expiration {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike,
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        now = self.Time
        time_stop = (
            self.expiration_stop_date is not None
            and now.date() == self.expiration_stop_date
            and now.hour == 15
            and now.minute >= 45
        )

        midpoint = None
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_symbol:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    if bid > 0 and ask > 0:
                        midpoint = (bid + ask) / 2.0
                    break

        profit_target = (
            midpoint is not None
            and self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        )

        if profit_target:
            self._submit_exit("50% profit target")
        elif time_stop:
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason: str):
