        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self._is_terminal(
            self.exit_ticket.Status
        ):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason,
        )
