        if len(self._five_minute_closes) > 20:
            self._five_minute_closes.pop(0)

        if len(self._five_minute_closes) < 20:
            return

        current_fast = sum(self._five_minute_closes[-5:]) / 5.0
        current_slow = sum(self._five_minute_closes[-20:]) / 20.0

        if len(self._five_minute_closes) == 20:
            return

        previous_values = self._five_minute_closes[:-1]
        previous_fast = sum(previous_values[-5:]) / 5.0
        previous_slow = sum(previous_values[-20:]) / 20.0

        bar_end_time = bucket_end.time()
        eligible_time = (
            time(9, 45) <= bar_end_time <= time(14, 30)
        )

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            eligible_time
            and bullish_crossover
            and self._held_option is None
            and self._entry_order_is_closed()
            and self._no_entry_date != self.Time.date()
        ):
            self._enter_from_current_chain(slice, float(close))

        self._minute_bars = {}

    def _enter_from_current_chain(self, slice: Slice, spy_price: float):
        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying expiration or call.")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = spy_price * 1.01
        selected = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == nearest_expiry
                and contract.Strike >= strike_floor
            )
        ]

        if not selected:
            self.Debug("Skipped entry: no qualifying strike.")
            return

        selected.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )
        contract = selected[0]

        self._entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="Bullish crossover entry"
        )
        self._entry_order_id = self._entry_ticket.OrderId

        self.Debug(
            f"Entry submitted: {contract.Symbol} "
            f"expiry={nearest_expiry} strike={contract.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self._entry_price is None or self._exit_submitted:
            return

        quote = slice.QuoteBars.get(self._held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2

        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self._held_option is None or self._exit_submitted:
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None:
            status = self._exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            ):
                self._exit_ticket.Cancel("Replacing with liquidation order")

        self._exit_ticket = self.MarketOrder(
            self._held_option,
            -quantity,
            tag=reason
        )
        self._exit_submitted = True
        self.Debug(f"Exit submitted: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_order_id is not None
            and order_event.OrderId == self._entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_order_id = None
                self._entry_ticket = None
                self.Debug(
                    f"Entry filled: {self._held_option} "
                    f"price={self._entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._entry_order_id = None
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")
            self._held_option = None
            self._entry_price = None
            self._exit_ticket = None
            self._exit_submitted = False

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"Unexpected exercise or assignment: {order_event.Symbol}"
            )
            self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and self._equity_liquidation_order_id is None:
            self.Debug(
                f"Unexpected SPY equity position detected: quantity={quantity}"
            )
            ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self._equity_liquidation_order_id = ticket.OrderId

    def _entry_order_is_closed(self):
        if self._entry_order_id is None:
            return True

        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value.date() if isinstance(date_value, datetime) else date_value.date() if hasattr(date_value, "date") else date_value

    def OnEndOfAlgorithm(self):
        if self._held_option is not None:
            self.Debug(
                f"Algorithm ended with option holding: {self._held_option}"
            )

