        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 400)
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately remove any unexpected SPY equity position.
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested:
            self.Debug(f"{self.Time}: Unexpected SPY equity position; liquidating.")
            self.MarketOrder(self.spy, -spy_holding.Quantity, "Unexpected assignment")

        # Expiration-day protection.
        if self.held_symbol is not None:
                expiry = self.held_symbol.ID.Date.date()
                if today >= expiry:
                    self.no_entry_date = today
                    self._cancel_entry_order()
                    if self.Portfolio[self.held_symbol].Invested:
                        self._liquidate_option("Expiration protection")
                    self._process_spy_bar(slice, allow_signal=False)
                    return

        self._process_spy_bar(slice, allow_signal=True)

        # Manage an existing option position on every minute Slice.
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            contract = self._get_current_contract(slice, self.held_symbol)

            if contract is not None:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0 and self.entry_price is not None:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.5 * self.entry_price:
                        self._liquidate_option("50% profit target")
                        return

            expiry = self.held_symbol.ID.Date.date()
            stop_date = self._previous_trading_day(expiry)

            if today == stop_date and self.Time.hour == 15 and self.Time.minute == 45:
                self._liquidate_option("Pre-expiration time stop")

    def _process_spy_bar(self, slice: Slice, allow_signal: bool):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        if end_time.hour < 9 or end_time.hour > 16:
            return
        if end_time.hour == 9 and end_time.minute < 31:
            return
        if end_time.hour == 16 and end_time.minute > 0:
            return

        bucket = self._bucket_end(end_time)

        if self.current_bucket is None:
            self.current_bucket = bucket

        if bucket != self.current_bucket:
            self._complete_bucket(self.current_bucket)
            self.current_bucket = bucket
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        # A five-minute bar is complete when its fifth minute has arrived.
        if end_time == bucket:
            self._complete_bucket(bucket)
            self.current_bucket = None
            self.bucket_bars = []

            if allow_signal:
                self._evaluate_entry(slice, bucket, bar.Close)

    def _complete_bucket(self, bucket_end):
        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        close = self.bucket_bars[-1].Close

        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        point = IndicatorDataPoint(self.spy, bucket_end, close)
        self.fast.Update(point)
        self.slow.Update(point)

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            self.fast.IsReady and
            self.slow.IsReady and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.last_bullish_cross = bullish_cross

    def _evaluate_entry(self, slice: Slice, bar_end, spy_price):
        if not getattr(self, "last_bullish_cross", False):
            return

        self.last_bullish_cross = False

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self._entry_order_open():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug(f"{self.Time}: Entry skipped; no option chain.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        if not contracts:
            self.Debug(f"{self.Time}: Entry skipped; empty option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped; no eligible expiration.")
            return

        selected_expiry = expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped; no eligible contract.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol, 1, "Bullish five-minute crossover entry"
        )
        self.Debug(f"{self.Time}: Entry submitted for {selected.Symbol}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: Entry filled {self.held_symbol} "
                    f"at {self.entry_price:.ด4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Unfilled
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled for {order_event.Symbol}.")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Unfilled
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(f"{self.Time}: Unexpected exercise or assignment received.")
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.MarketOrder(self.spy, -holding.Quantity, "Assignment liquidation")

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol, -quantity, reason
            )
            self.Debug(f"{self.Time}: Exit submitted: {reason}.")

    def _cancel_entry_order(self):
        if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
            self.entry_ticket.Cancel("Expiration protection")

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status.IsOpen()
        )

    def _get_current_contract(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while candidate.weekday() >= 5 or not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _bucket_end(self, end_time):
        minutes_since_0930 = (end_time.hour * 60 + end_time.minute) - (9 * 60 + 30)
        bucket_number = (minutes_since_0930 - 1) // 5 + 1
        end_minutes = 9 * 60 + 30 + bucket_number * 5
        return datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            end_minutes // 60,
            end_minutes % 60
        )


def time(hour, minute):
    return datetime(2000, 1, 1, hour, minute).time()

