        minutes_since_0930 = (end_time.hour * 60 + end_time.minute) - (9 * 60 + 30)
        bucket_number = (minutes_since_0930 - 1) // 5 + 1
        end_minutes = 9 * 60 + 30 + bucket_number * 5
        return datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            end_minutes // 60,
            end_minutes % 60
        )


def time(hour, minute):
    return datetime(2000, 1, 1, hour, minute).time()

