            minutes=bucket_minute
        )

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_minute_bars = {}

        self.current_minute_bars[end] = bar

        if end != bucket_end:
            return None

        bars = [
            self.current_minute_bars.get(bucket_end - timedelta(minutes=i))
            for i in range(1, 6)
        ]
        self.current_minute_bars = {}

        if any(b is None for b in bars):
            return None

        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            bars[-1].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[0].Close,
