        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entries_date = current_date
            self._submit_option_exit("Expiration protection", quantity)
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.hour > 15
            or (
                current_date == previous_trading_day
                and self.Time.hour == 15
                and self.Time.minute >= 45
            )
        ):
            self._submit_option_exit("Pre-expiration time stop", quantity)
            return

        if self._exit_order_open():
            return

        chain = slice.OptionChains.get(self.spy_option.Symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self.held_symbol),
            None,
        )
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50 percent profit target", quantity)

    def _submit_option_exit(self, reason, quantity):
        if quantity <= 0 or self.held_symbol is None:
            return

        if self._exit_order_open():
            self.Transactions.CancelOpenOrders(self.held_symbol)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} at {:.2f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Interrupted,
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Interrupted,
            ):
                self.exit_ticket = None

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            if not self.equity_liquidation_submitted:
                self.Debug("Unexpected SPY exercise or assignment; liquidating.")
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Unexpected exercise or assignment liquidation",
                )
                self.equity_liquidation_submitted = True
        else:
            self.equity_liquidation_submitted = False

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status
            in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status
            in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        )

