from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCrossoverOptionAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_today = False

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        if self.bucket_date != current_date:
            self.bucket_date = current_date
            self.bucket_end = None
            self.bucket_bars = []
            self.no_entry_today = False

        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._manage_held_option(data)

        if self.spy_symbol not in data.Bars:
            return

        minute_bar = data.Bars[self.spy_symbol]
        self._process_minute_bar(minute_bar, data)

    def _process_minute_bar(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.EndTime
        if end_time.date() != self.Time.date():
            return

        session_start = end_time.replace(hour=9, minute=30, second=0, microsecond=0)
        session_end = end_time.replace(hour=16, minute=0, second=0, microsecond=0)

        if end_time <= session_start or end_time > session_end:
            return

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            minute=0, second=0, microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self.bucket_end is None:
            self.bucket_end = bucket_end
        elif bucket_end != self.bucket_end:
            self._finalize_bucket(data)
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        if end_time == self.bucket_end:
            self._finalize_bucket(data)
            self.bucket_bars = []
            self.bucket_end = None

    def _finalize_bucket(self, data: Slice):
        if self.bucket_end is None or len(self.bucket_bars) != 5:
            return

        bars = self.bucket_bars
        close = bars[-1].Close

        had_ready_averages = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if had_ready_averages else None
        previous_slow = self.slow.Current.Value if had_ready_averages else None

        self.fast.Update(self.bucket_end, close)
        self.slow.Update(self.bucket_end, close)

        if not (had_ready_averages and self.fast.IsReady and self.slow.IsReady):
            return

        eligible_time = (
            self.bucket_end.hour == 9 and self.bucket_end.minute >= 45
        ) or (
            self.bucket_end.hour > 9 and self.bucket_end.hour < 14
        ) or (
            self.bucket_end.hour == 14 and self.bucket_end.minute <= 30
        )

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_crossover:
            self._try_enter(data, float(close))

    def _try_enter(self, data: Slice, spy_price: float):
        if self.no_entry_today or self._has_option_position() or self._entry_is_open():
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = data.OptionChains[self.option_symbol]
        contracts = list(chain.Contracts.Values)

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiry {} strike {}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _manage_held_option(self, data: Slice):
        if not self._has_option_position() or self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        today = self.Time.date()

        if self._is_time_stop_day(expiry, today) and self.Time.hour == 15 and self.Time.minute >= 45:
            self._submit_exit("Expiration-eve time stop")
            return

        if self.option_symbol not in data.OptionChains:
            return

        chain = data.OptionChains[self.option_symbol]
        held_contract = None

        for contract in chain.Contracts.Values:
            if contract.Symbol == self.held_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if not self._has_option_position() or self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_today = True
            self._submit_exit("Expiration processing liquidation")

    def _submit_exit(self, reason: str):
        if not self._has_option_position() or self.held_symbol is None:
            return

        if self._exit_is_open():
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
