from AlgorithmImports import *
from datetime import timedelta


class SpyOptionMovingAverageAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.held_option = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_dates = set()
        self.equity_liquidation_ticket = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy:
            return

        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        if (
            bullish_cross
            and local_end.time() >= time(9, 45)
            and local_end.time() <= time(14, 30)
        ):
            self.pending_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, slice):
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition(today)
        self.HandleExpirationProcessing(today)
        self.EvaluateHeldOptionExit(slice, today)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice, today)

    def TryEnter(self, slice, today):
        if today in self.no_entry_dates:
            return

        if self.held_option is not None:
            return

        if self.IsOrderOpen(self.entry_ticket):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        eligible = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        contracts = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, nearest_expiry, selected.Strike
            )
        )

    def EvaluateHeldOptionExit(self, slice, today):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0 or self.IsOrderOpen(self.exit_ticket):
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if today >= expiry_date:
            self.no_entry_dates.add(today)
            self.SubmitExit("expiration processing")
            return

        previous_trading_day = self.GetPreviousTradingDay(expiry_date)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        quote = self.GetCurrentOptionQuote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0 or self.IsOrderOpen(self.exit_ticket):
            return

        if self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0}, quantity {1}".format(
                reason, quantity
            )
        )

    def HandleExpirationProcessing(self, today):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()
        if today >= expiry_date:
            self.no_entry_dates.add(today)
            if self.IsOrderOpen(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing")
            self.SubmitExit("expiration processing")

    def HandleUnexpectedEquityPosition(self, today):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.no_entry_dates.add(today)

        if self.equity_liquidation_ticket is None or not self.IsOrderOpen(
            self.equity_liquidation_ticket
        ):
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity."
            )
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

    def GetCurrentOptionQuote(self, slice, symbol):
        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def GetPreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def IsOrderOpen(ticket):
        if ticket is None:
            return False

        return ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        }

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.FillQuantity > 0
            ):
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_option, self.entry_price
                    )
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None

            elif order_event.Symbol == self.spy:
                self.no_entry_dates.add(self.Time.date())
                self.Debug(
                    "Unexpected exercise or assignment event: liquidating SPY."
                )
                self.HandleUnexpectedEquityPosition(self.Time.date())

        elif (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            }
        ):
            self.Debug("Entry order did not fill.")
            self.entry_ticket = None

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            }
        ):
            self.exit_ticket = None

