class SpyBullishCrossoverOptionAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option = option

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self.bucket_key = None
        self.bucket = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_replacement_date = None
        self.spy_cleanup_submitted = False

    def OnData(self, data: Slice):
        self._liquidate_unexpected_spy_position()
        self._process_held_option(data)

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        bar = data.Bars[self.spy] if self.spy in data.Bars else None
        if bar is None:
            return

        self._update_five_minute_bar(bar, data)

    def _update_five_minute_bar(self, minute_bar, data):
        local_time = minute_bar.Time
        total_minutes = local_time.hour * 60 + local_time.minute
