            self.bucket = {
                "count": 0,
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": minute_bar.Volume
            }
        else:
            self.bucket["high"] = max(self.bucket["high"], minute_bar.High)
            self.bucket["low"] = min(self.bucket["low"], minute_bar.Low)
            self.bucket["close"] = minute_bar.Close
