            self.Debug(
                f"Unexpected exercise or assignment: {order_event.Symbol}"
            )
            self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self.spy_cleanup_submitted = False
            return

        if self.spy_cleanup_submitted:
            return

        self.Debug(
            f"Unexpected SPY equity position; liquidating quantity={quantity}"
        )
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )
        self.spy_cleanup_submitted = True

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _cancel_open_exit_order(self):
        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Canceled for replacement liquidation")
        self.exit_ticket = None

