        self._blocked_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()
        self._process_expiration(current_date)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._process_spy_minute(spy_bar, slice)

        if self._held_option is not None and self._entry_price is not None:
            self._evaluate_exits(slice)

    def _process_spy_minute(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime
        local_end = end_time

        minute_of_day = local_end.hour * 60 + local_end.minute
        bucket_end_minutes = ((minute_of_day + 4) // 5) * 5
        bucket_end = local_end.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60,
            second=0,
            microsecond=0
        )

        if self._bar_bucket_end is not None and bucket_end != self._bar_bucket_end:
            self._complete_five_minute_bar(self._bar_bucket_end, slice)

        if self._bar_bucket_end != bucket_end:
            self._bar_bucket_end = bucket_end
            self._minute_bars = {}

        self._minute_bars[local_end] = minute_bar

        if local_end.minute % 5 == 0:
            self._complete_five_minute_bar(bucket_end, slice)
            self._bar_bucket_end = None
            self._minute_bars = {}

    def _complete_five_minute_bar(self, bucket_end, slice: Slice):
        if not self._minute_bars:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]
        if any(t not in self._minute_bars for t in expected_times):
            return

        closes = [self._minute_bars[t].Close for t in expected_times]
        five_minute_close = closes[-1]

        self._previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self._previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, five_minute_close)
        self.slow.Update(bucket_end, five_minute_close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return
        if self._previous_fast is None or self._previous_slow is None:
            return

        bullish_crossover = (
            self._previous_fast <= self._previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        eligible_time = (
            bucket_end.hour > 9 or
            (bucket_end.hour == 9 and bucket_end.minute >= 45)
        ) and (
            bucket_end.hour < 14 or
            (bucket_end.hour == 14 and bucket_end.minute <= 30)
        )

        if (
            bullish_crossover and
            eligible_time and
            self._last_signal_bar != bucket_end
        ):
            self._last_signal_bar = bucket_end
            self._try_enter(slice, five_minute_close)

    def _try_enter(self, slice: Slice, spy_price: float):
