from AlgorithmImports import *
from datetime import timedelta


class SpyBullishOptionAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                     .Strikes(-100, 100)
                                     .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.blocked_dates = set()
        self.assignment_liquidation_submitted = False

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self.ProcessExpiration
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.ProcessTimeStop
        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_option is not None:
            if self.Time.date() >= self.held_option.ID.Date.date():
                self.blocked_dates.add(self.Time.date())
                self.SubmitExit("expiration processing")
                return

            self.CheckProfitTarget(slice)

        if self.Time.date() in self.blocked_dates:
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self.UpdateFiveMinuteBar(bar, slice)

    def UpdateFiveMinuteBar(self, bar: TradeBar, slice: Slice):
        local_time = self.Time
        if local_time.weekday() >= 5:
            return

        minute = local_time.replace(second=0, microsecond=0)
        session_start = minute.replace(hour=9, minute=30)
        session_end = minute.replace(hour=16, minute=0)

        if minute < session_start or minute >= session_end:
            return

        minutes_from_open = int((minute - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.bucket_date != minute.date() or self.bucket_start != bucket_start:
            if self.bucket_bars and self.bucket_date == minute.date():
                self.EmitFiveMinuteBarIfComplete(slice)

            self.bucket_date = minute.date()
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[minute] = bar

    def EmitFiveMinuteBarIfComplete(self, slice: Slice):
        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self.bucket_bars for t in expected):
            self.bucket_bars = {}
            return

        closes = [self.bucket_bars[t].Close for t in expected]
        close = closes[-1]
        bar_end = self.bucket_start + timedelta(minutes=5)

        self.fast.Update(IndicatorDataPoint(bar_end, close))
        self.slow.Update(IndicatorDataPoint(bar_end, close))

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossover = (
            self.fast.IsReady and
            self.slow.IsReady and
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_bars = {}

        if not crossover:
            return

        end_time = bar_end.time()
        eligible_start = (9, 45)
        eligible_end = (14, 30)

        if not (
            (end_time.hour, end_time.minute) >= eligible_start and
            (end_time.hour, end_time.minute) <= eligible_end
        ):
            return

        if self.HasOptionPositionOrOpenEntry():
            return

        self.TryEnter(slice, close)

    def TryEnter(self, slice: Slice, spy_price: float):
        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expirations[0]
        threshold = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={selected.Expiry.date()} strike={selected.Strike}"
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option.Symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def ProcessTimeStop(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = (
            self.Securities[self.spy]
            .Exchange
            .Hours
            .GetPreviousTradingDay(expiry_date)
            .date()
        )

        if self.Time.date() == previous_trading_day:
            self.SubmitExit("expiration time stop")

    def ProcessExpiration(self):
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()
            if expiry_date <= self.Time.date():
                self.blocked_dates.add(self.Time.date())
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation exit")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_option.Symbol} ({reason})")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.Securities[order_event.Symbol].Symbol
                self.entry_price = order_event.FillPrice
                expiry_date = self.held_option.ID.Date.date()

                self.time_stop_date = (
                    self.Securities[self.spy]
                    .Exchange
                    .Hours
                    .GetPreviousTradingDay(expiry_date)
                    .date()
                )

                self.Debug(
                    f"Entry filled: {self.held_option.Symbol} "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and self.entry_ticket.Status != OrderStatus.PartiallyFilled:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.time_stop_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            f"Unexpected option exercise or assignment: {assignment_event.Symbol}"
        )
        self.HandleUnexpectedEquityPosition()

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self.assignment_liquidation_submitted:
            self.Debug(
                f"Unexpected SPY equity position detected: quantity={quantity}; "
                "liquidating immediately."
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.assignment_liquidation_submitted = True

    def HasOptionPositionOrOpenEntry(self) -> bool:
        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return True

        if self.held_option is not None:
            return self.Portfolio[self.held_option.Symbol].Quantity != 0

        return False

    @staticmethod
    def IsOpen(ticket: OrderTicket) -> bool:
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

