from AlgorithmImports import *
from collections import defaultdict, deque
from datetime import timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1.0,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self._minute_buckets = defaultdict(dict)
        self._closes = deque(maxlen=20)
        self._fast = None
        self._slow = None
        self._previous_fast = None
        self._previous_slow = None

        self._entry_ticket = None
        self._entry_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._blocked_entry_date = None
        self._spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_option_position(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._collect_minute_bar(spy_bar, slice)

    def _collect_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        if bar_time.weekday() >= 5:
            return

        if bar_time.hour < 9 or (bar_time.hour == 9 and bar_time.minute < 30):
            return
        if bar_time.hour > 16 or (bar_time.hour == 16 and bar_time.minute > 0):
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        minute_index = bar_time.minute % 5
        bucket = self._minute_buckets[bucket_start]
        bucket[minute_index] = bar

        if len(bucket) < 5 or any(i not in bucket for i in range(5)):
            return

        bars = [bucket[i] for i in range(5)]
        if any(
            bars[i].Time != bucket_start + timedelta(minutes=i)
            for i in range(5)
        ):
            del self._minute_buckets[bucket_start]
            return

        close = bars[-1].Close
        bar_end = bucket_start + timedelta(minutes=5)
        del self._minute_buckets[bucket_start]

        self._update_moving_averages(close, bar_end, slice)

    def _update_moving_averages(self, close: float, bar_end, slice: Slice):
        if len(self._closes) == 20:
            self._closes.popleft()
        self._closes.append(float(close))

        if len(self._closes) < 20:
            return

        self._previous_fast = self._fast
        self._previous_slow = self._slow
        self._fast = sum(list(self._closes)[-5:]) / 5.0
        self._slow = sum(self._closes) / 20.0

        if self._previous_fast is None or self._previous_slow is None:
            return

        crossover = (
            self._previous_fast <= self._previous_slow
            and self._fast > self._slow
        )

        if not crossover:
            return

        if not (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)):
            return
        if not (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)):
            return

        self._try_enter(slice, bar_end.date())

    def _try_enter(self, slice: Slice, signal_date):
        if self._blocked_entry_date == signal_date:
            return

        if self._entry_ticket is not None and self._ticket_is_open(self._entry_ticket):
            return

        if self._entry_symbol is not None:
            holding = self.Portfolio[self._entry_symbol]
            if holding.Quantity > 0:
                return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped option selection: SPY price unavailable.")
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiration_date = contract.Expiration.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiration_date >= signal_date + timedelta(days=7)
                    and contract.Strike >= 1.01 * spy_bar.Close
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped option selection: no qualifying contract.")
            return

        nearest_expiration = min(
            contract.Expiration.date() for contract in contracts
        )
        candidates = [
            contract for contract in contracts
            if contract.Expiration.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_symbol = selected.Symbol
        self._entry_price = None
        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol,
                nearest_expiration,
                selected.Strike
            )
        )

    def _process_option_position(self, slice: Slice):
        if self._entry_symbol is None:
            return

        holding = self.Portfolio[self._entry_symbol]
        if holding.Quantity <= 0:
            return

        expiration_date = self._entry_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration_date:
            self._blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)
        if (
            current_date == previous_trading_day
            and self.Time.hour >= 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")
            return

        if self._entry_price is None or self._entry_price <= 0:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain.Contracts.Values:
                if candidate.Symbol == self._entry_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self._entry_symbol is None:
            return

        holding = self.Portfolio[self._entry_symbol]
        if holding.Quantity <= 0:
            return

        if self._exit_ticket is not None and self._ticket_is_open(self._exit_ticket):
            return

        quantity = -holding.Quantity
        self._exit_ticket = self.MarketOrder(self._entry_symbol, quantity)
        self.Debug(
            "Exit submitted: {} reason={}".format(
                self._entry_symbol,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
            and order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled)
        ):
            if order_event.FillPrice > 0:
                self._entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} price={}".format(
                        self._entry_symbol,
                        self._entry_price
                    )
                )

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self._entry_symbol))
            self._exit_ticket = None
            self._entry_symbol = None
            self._entry_price = None
            self._entry_ticket = None

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self._spy_liquidation_ticket is None
            or not self._ticket_is_open(self._spy_liquidation_ticket)
        ):
            self.Debug(
                "Unexpected SPY exercise/assignment position; liquidating."
            )
            self._spy_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity
            )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)
        return date_value

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

