        self._handle_unexpected_equity_position(current_date)
        self._handle_expiration_processing(current_date)

        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        if spy_bar is not None:
            self._process_minute_bar(spy_bar)

        if self.held_option is not None:
            self._evaluate_option_exit(data, current_date)

        if self.pending_signal:
            self.pending_signal = False
            self._evaluate_entry(data, current_date)

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime.replace(second=0, microsecond=0)
        t = end_time.time()

        if t < time(9, 31) or t > time(16, 0):
            return

        total_minutes = t.hour * 60 + t.minute
        bucket_end_minute = 35 + ((total_minutes - 35) // 5) * 5
        bucket_hour = bucket_end_minute // 60
        bucket_minute = bucket_end_minute % 60
        bucket_end = end_time.replace(hour=bucket_hour, minute=bucket_minute)

        if self.current_bucket_end is None or bucket_end != self.current_bucket_end:
            if self.current_bucket_end is not None:
                self._finalize_bucket()

            self.current_bucket_end = bucket_end
            self.current_bucket_bars = []

        self.current_bucket_bars.append((end_time, bar))

        if end_time == self.current_bucket_end:
            self._finalize_bucket()
            self.current_bucket_end = None
            self.current_bucket_bars = []

    def _finalize_bucket(self):
        if self.current_bucket_end is None:
            return

        expected_times = [
            self.current_bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]
        actual_times = [item[0] for item in self.current_bucket_bars]

        if actual_times != expected_times:
            return

        close = self.current_bucket_bars[-1][1].Close
        previous_fast = (
            sum(self.fast_values) / len(self.fast_values)
            if len(self.fast_values) == 5 else None
        )
        previous_slow = (
            sum(self.slow_values) / len(self.slow_values)
            if len(self.slow_values) == 20 else None
        )

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = sum(self.fast_values) / 5
        current_slow = sum(self.slow_values) / 20

        end_time = self.current_bucket_end.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if (
            eligible_time
            and previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
