            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Strike >= strike_threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying strike.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} strike {:.2f} expiration {}".format(
                selected.Symbol, selected.Strike, expiration
            )
        )

    def _evaluate_option_exit(self, data: Slice, current_date):
        if self.held_option is None:
            return

