            self.expiration_date is not None
            and current_date < self.expiration_date
            and self.Time.hour == 15
            and self.Time.minute == 45
            and self.last_time_stop_date != current_date
            and self._is_immediately_preceding_trading_day(
                current_date, self.expiration_date
            )
