            return

        contract = self._find_contract(data, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._cancel_open_exit_orders()
            self._submit_exit("profit target")

    def _handle_expiration_processing(self, current_date):
        if self.held_option is None or self.expiration_date is None:
            return

        if current_date >= self.expiration_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration protection")

    def _handle_unexpected_equity_position(self, current_date):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.no_entry_date = current_date
            if self.equity_cleanup_ticket is None or self._order_closed(self.equity_cleanup_ticket):
                self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
                self.equity_cleanup_ticket = self.MarketOrder(
                    self.spy, -holding.Quantity
                )

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is None or self._order_closed(self.exit_ticket):
            self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
            self.Debug("Exit submitted ({}): {}".format(reason, self.held_option))

    def _find_contract(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and not self._order_closed(self.entry_ticket)
        )

    def _order_closed(self, ticket):
        return ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        )

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and not self._order_closed(self.exit_ticket):
            self.exit_ticket.Cancel("Profit target reached")

    def _is_immediately_preceding_trading_day(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while candidate >= current_date:
            if exchange_hours.IsDateOpen(candidate):
                return candidate == current_date
            candidate -= timedelta(days=1)

        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = self.held_option.ID.Date.date()
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option, self.entry_price
                    )
                )
                self.entry_ticket = None

            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug("Entry order failed or canceled.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {:.4f}".format(
                    self.exit_ticket.Symbol, order_event.FillPrice
                ))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

