from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyOptionBullishCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        if self.spy in slice.Bars:
            self.consolidator.Update(slice.Bars[self.spy])

        today = self.Time.date()

        # Do not intentionally carry an option into its expiration date.
        if self.held_symbol is not None and self.held_expiry is not None:
            if today >= self.held_expiry:
                self.blocked_entry_date = today
                if self.Portfolio[self.held_symbol].Quantity > 0:
                    self.SubmitExit("expiration processing")
                return

        if self.held_symbol is not None:
            quantity = self.Portfolio[self.held_symbol].Quantity

            if quantity > 0 and self.held_expiry is not None:
                previous_trading_day = self.PreviousTradingDay(self.held_expiry)

                if (
                    today == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self.SubmitExit("expiration time stop")
                    return

                if self.exit_ticket is None or not self.IsOpen(self.exit_ticket):
                    contract = self.GetCurrentContract(slice, self.held_symbol)

                    if contract is not None:
                        bid = float(contract.BidPrice)
                        ask = float(contract.AskPrice)

                        if (
                            bid > 0
                            and ask > 0
                            and self.entry_price is not None
                        ):
                            midpoint = (bid + ask) / 2.0
                            if midpoint >= 1.50 * self.entry_price:
                                self.SubmitExit("50% profit target")

            return

        # A signal is evaluated exactly once, using the Slice in which the
        # completed five-minute bar became available.
        if self.pending_signal:
            self.pending_signal = False

            if today == self.blocked_entry_date:
                return

            if self.EntryOrderIsOpen():
                return

            self.TryEnter(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end_time = bar.EndTime
        end_date = end_time.date()
        end_clock = end_time.time()

        # Require New York regular-session five-minute boundaries. This also
        # prevents extended-session bars from warming the averages.
        if end_clock < time(9, 35) or end_clock > time(16, 0):
            return

        if end_clock.minute % 5 != 0:
            return

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        fast_current = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow_current = sum(self.slow_window[i] for i in range(20)) / 20.0

        fast_previous = (
            sum(self.fast_window[i] for i in range(1, 6)) / 5.0
        )
        slow_previous = (
            sum(self.slow_window[i] for i in range(1, 21)) / 20.0
        )

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        if (
            eligible_start <= end_clock <= eligible_end
            and fast_previous <= slow_previous
            and fast_current > slow_current
        ):
            self.pending_signal = True

    def TryEnter(self, slice: Slice):
        chain = None

        try:
            if self.option_symbol in slice.OptionChains:
                chain = slice.OptionChains[self.option_symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        current_price = None
        if self.spy in slice.Bars:
            current_price = float(slice.Bars[self.spy].Close)
        elif self.Securities[self.spy].Price > 0:
            current_price = float(self.Securities[self.spy].Price)

        if current_price is None or current_price <= 0:
            self.Debug("Skipped entry: unavailable SPY price")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * current_price

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            if reason == "50% profit target":
                self.exit_ticket.Cancel("profit target superseded prior exit")
            else:
                return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {0}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.held_expiry = self.Securities[
                    order_event.Symbol
                ].Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol, self.entry_price
                    )
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {0}".format(order_event.Symbol))
            self.held_symbol = None
            self.entry_price = None
            self.held_expiry = None
            self.exit_ticket = None
            self.entry_ticket = None

        if (
            order_event.EventType == OrderEventType.OptionAssignment
            or (
                order_event.Symbol.SecurityType == SecurityType.Equity
                and order_event.Direction != OrderDirection.Hold
            )
        ):
