from AlgorithmImports import *
from datetime import timedelta, datetime


class SpyBullishCrossoverOptions(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.pending_signal = None
        self.no_entry_today = False
        self.equity_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        was_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if was_ready else None
        previous_slow = self.slow.Current.Value if was_ready else None

        self.fast.Update(bar.End, bar.Close)
        self.slow.Update(bar.End, bar.Close)

        if not was_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        end_time = bar.End
        if not (
            end_time.hour > 9
            or (end_time.hour == 9 and end_time.minute >= 45)
        ):
            return

        if end_time.hour > 14 or (
            end_time.hour == 14 and end_time.minute > 30
        ):
            return

        if self.fast.Current.Value > self.slow.Current.Value and \
           previous_fast <= previous_slow:
            self.pending_signal = (end_time, bar.Close)

    def OnData(self, slice):
        today = self.Time.date()

        if self.equity_liquidation_order_id is not None:
            if self.Portfolio[self.spy.Symbol].Quantity == 0:
                self.equity_liquidation_order_id = None
            else:
                return

        equity_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if equity_quantity != 0:
            self.no_entry_today = True
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position; liquidating "
                f"{equity_quantity} shares."
            )
            if self.equity_liquidation_order_id is None:
                order = self.MarketOrder(
                    self.spy.Symbol,
                    -equity_quantity,
                    tag="Unexpected exercise or assignment liquidation"
                )
                if order is not None:
                    self.equity_liquidation_order_id = order.OrderId
            return

        if self.held_symbol is not None:
            held_quantity = self.Portfolio[self.held_symbol].Quantity
            if held_quantity <= 0 and self.exit_order_id is None:
                self._clear_position_state()

        if self.held_symbol is not None:
            expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry:
                self.no_entry_today = True
                self._submit_exit("Expiration protection liquidation")
            elif self._is_trading_day_before_expiration(today, expiry):
                if self.Time.hour == 15 and self.Time.minute == 45:
                    self._submit_exit("Pre-expiration time stop")
            else:
                contract = slice.OptionChains.get(self.option.Symbol)
                if contract is not None:
                    option_data = contract.get(self.held_symbol)
                    if option_data is not None:
                        bid = option_data.BidPrice
                        ask = option_data.AskPrice
                        if bid > 0 and ask > 0 and self.entry_price is not None:
                            midpoint = (bid + ask) / 2.0
                            if midpoint >= 1.5 * self.entry_price:
                                self._submit_exit("50 percent profit target")

        if self.pending_signal is None:
            return

        self.pending_signal = None

        if self.no_entry_today or self.held_symbol is not None:
            return

        if self.entry_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Skipped entry; no option chain.")
            return

        algorithm_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not eligible:
            self.Debug(
                f"{self.Time}: Skipped entry; no expiration satisfies the rule."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        same_expiry = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
        ]

        _, spy_price = self.pending_signal if False else (None, None)
        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Skipped entry; invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price
        strike_eligible = [
            contract for contract in same_expiry
            if contract.Strike >= minimum_strike
        ]

        if not strike_eligible:
            self.Debug(
                f"{self.Time}: Skipped entry; no contract meets strike rule."
            )
            return

        selected = min(
            strike_eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.held_symbol = selected.Symbol
        self.entry_price = None
        order = self.MarketOrder(
            self.held_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        if order is None:
            self.held_symbol = None
            self.Debug(f"{self.Time}: Entry order could not be submitted.")
        else:
            self.entry_order_id = order.OrderId
            self.Debug(
                f"{self.Time}: Entering {self.held_symbol} at market; "
                f"expiry {nearest_expiry}, strike {selected.Strike}."
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ) and order_event.FillQuantity > 0:
                if self.entry_price is None:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"{self.Time}: Entry filled at "
                        f"{self.entry_price:.4f}."
                    )

                if order_event.Status == OrderStatus.Filled:
                    self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(
                    f"{self.Time}: Entry order failed: "
                    f"{order_event.Status}."
                )
                self.entry_order_id = None
                if self.held_symbol is not None and \
                   self.Portfolio[self.held_symbol].Quantity <= 0:
                    self._clear_position_state()

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {self.held_symbol}."
                )
                self.exit_order_id = None
                self._clear_position_state()
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_order_id = None

        if (
            self.equity_liquidation_order_id is not None
            and order_event.OrderId == self.equity_liquidation_order_id
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            )
        ):
            self.equity_liquidation_order_id = None

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.CancelOrder(order.Id, "Canceling competing exit order")

        order = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        if order is not None:
            self.exit_order_id = order.OrderId
            self.Debug(f"{self.Time}: Exit submitted: {reason}.")

    def _is_trading_day_before_expiration(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        date = expiry_date - timedelta(days=1)
        while date > current_date:
            date -= timedelta(days=1)

        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = datetime.combine(date, datetime.min.time())
        return date == current_date and exchange_hours.IsDateOpen(candidate)

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None

