            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not eligible:
            self.Debug(
                f"{self.Time}: Skipped entry; no expiration satisfies the rule."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        same_expiry = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
        ]

        _, spy_price = self.pending_signal if False else (None, None)
        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Skipped entry; invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price
        strike_eligible = [
            contract for contract in same_expiry
            if contract.Strike >= minimum_strike
        ]

        if not strike_eligible:
            self.Debug(
                f"{self.Time}: Skipped entry; no contract meets strike rule."
            )
            return

        selected = min(
            strike_eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.held_symbol = selected.Symbol
        self.entry_price = None
        order = self.MarketOrder(
            self.held_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        if order is None:
            self.held_symbol = None
            self.Debug(f"{self.Time}: Entry order could not be submitted.")
        else:
            self.entry_order_id = order.OrderId
            self.Debug(
                f"{self.Time}: Entering {self.held_symbol} at market; "
                f"expiry {nearest_expiry}, strike {selected.Strike}."
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ) and order_event.FillQuantity > 0:
                if self.entry_price is None:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"{self.Time}: Entry filled at "
                        f"{self.entry_price:.4f}."
                    )

                if order_event.Status == OrderStatus.Filled:
                    self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(
                    f"{self.Time}: Entry order failed: "
                    f"{order_event.Status}."
                )
                self.entry_order_id = None
                if self.held_symbol is not None and \
                   self.Portfolio[self.held_symbol].Quantity <= 0:
                    self._clear_position_state()

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {self.held_symbol}."
                )
                self.exit_order_id = None
                self._clear_position_state()
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_order_id = None

        if (
            self.equity_liquidation_order_id is not None
            and order_event.OrderId == self.equity_liquidation_order_id
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            )
        ):
            self.equity_liquidation_order_id = None

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.CancelOrder(order.Id, "Canceling competing exit order")

        order = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        if order is not None:
            self.exit_order_id = order.OrderId
            self.Debug(f"{self.Time}: Exit submitted: {reason}.")

    def _is_trading_day_before_expiration(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        date = expiry_date - timedelta(days=1)
        while date > current_date:
            date -= timedelta(days=1)

        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = datetime.combine(date, datetime.min.time())
        return date == current_date and exchange_hours.IsDateOpen(candidate)

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None

