        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.held_option = None
        self.exit_ticket = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._liquidate_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                self._evaluate_open_position(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self.consolidator.Update(spy_bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        fast_was_ready = self.fast.IsReady
        slow_was_ready = self.slow.IsReady

        prior_fast = float(self.fast.Current.Value) if fast_was_ready else None
        prior_slow = float(self.slow.Current.Value) if slow_was_ready else None

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if fast_was_ready and slow_was_ready:
            self.previous_fast = prior_fast
            self.previous_slow = prior_slow

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        if (
            self.previous_fast is None
            or self.previous_slow is None
            or self.previous_fast > self.previous_slow
            or current_fast <= current_slow
        ):
            return

        bar_time = bar.EndTime
        if not (bar_time.hour == 9 and bar_time.minute >= 45
                or 10 <= bar_time.hour <= 13
                or bar_time.hour == 14 and bar_time.minute <= 30):
            return

        self._try_enter(bar)

    def _try_enter(self, bar: TradeBar):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_option is not None or self._order_is_open(self.entry_ticket):
            return

        chains = list(self.CurrentSlice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = None
        for candidate in chains:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: SPY option chain unavailable.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = float(bar.Close) * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiry,
                float(selected.Strike)
            )
        )

    def _evaluate_open_position(self, slice: Slice):
        if self.held_option is None:
            return

        current_date = self.Time.date()
        expiry_date = self.held_option.ID.Date.date()

        previous_trading_day = self._previous_trading_day(expiry_date)
        is_time_stop = (
            current_date == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        )

        midpoint = self._current_option_midpoint(slice, self.held_option.Symbol)

        if midpoint is not None and self.entry_price is not None:
            if midpoint >= 1.50 * float(self.entry_price):
                self._submit_exit("50% profit target")
                return

        if is_time_stop:
            self._submit_exit("pre-expiration time stop")

    def _current_option_midpoint(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid is None or ask is None:
                    return None

                bid = float(bid)
                ask = float(ask)

                if bid <= 0 or ask <= 0:
                    return None

                return (bid + ask) / 2.0

        return None

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity <= 0:
            return

        if self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity
        )
        self.Debug(
            "Exit submitted ({}): {}".format(reason, self.held_option.Symbol)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.held_option = self.Securities[self.entry_symbol]
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.entry_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill: {}".format(
                    self.entry_symbol
                ))

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.held_option = None
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.blocked_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment detected; "
                "liquidating resulting SPY position."
            )
            self._liquidate_unexpected_spy_position()

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.blocked_entry_date = self.Time.date()

        for ticket in self.Transactions.GetOpenOrders(self.spy):
            ticket.Cancel("Unexpected SPY exercise or assignment position")

        self.MarketOrder(self.spy, -quantity)
        self.Debug(
            "Unexpected SPY equity position liquidated: {} shares.".format(
                quantity
            )
        )

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

