from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyOptionBullishCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(days=365))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.current_bucket = None
        self.bucket_bars = {}

        self.previous_fast = None
        self.previous_slow = None

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_liquidation_ticket = None
        self.expiration_blocked_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        current_date = self.Time.date()
        if (
            self.held_symbol is not None
            and self.held_symbol in self.Securities
            and self.held_symbol.ID.Date.date() <= current_date
        ):
            self.expiration_blocked_date = current_date
            self._submit_exit("expiration-date liquidation")

        self._evaluate_held_position(slice)

        if self.spy.Symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy.Symbol]
        bar_time = minute_bar.Time

        if bar_time.date() != current_date:
            return

        if not (time(9, 30) <= bar_time.time() < time(16, 0)):
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0,
        )

        if self.current_bucket is None:
            self.current_bucket = bucket_start
        elif bucket_start != self.current_bucket:
            self.bucket_bars = {}
            self.current_bucket = bucket_start

        self.bucket_bars[bar_time.minute] = minute_bar

        expected_minutes = {
            bucket_start.minute + offset for offset in range(5)
        }

        if not expected_minutes.issubset(self.bucket_bars.keys()):
            return

        bars = [
            self.bucket_bars[bucket_start.minute + offset]
            for offset in range(5)
        ]

        consolidated_close = bars[-1].Close
        consolidated_end = bucket_start + timedelta(minutes=5)

        self._process_five_minute_close(
            consolidated_end,
            consolidated_close,
            slice,
        )

        self.bucket_bars = {}

    def _process_five_minute_close(self, bar_end, close, slice):
        self.closes.append(float(close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.expiration_blocked_date == self.Time.date():
            return

        if self._has_option_holding() or self._entry_order_is_open():
            return

        self._try_enter(slice, float(close))

    def _try_enter(self, slice, spy_price):
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = None
        for candidate in slice.OptionChains:
            if candidate.Symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = [
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        selected_expiry = min(eligible_expiries)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        contract = min(
            candidates,
            key=lambda item: (float(item.Strike), str(item.Symbol)),
        )

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}.".format(
                contract.Symbol,
                selected_expiry,
                contract.Strike,
            )
        )

    def _evaluate_held_position(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.held_symbol not in self.Securities:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.expiration_blocked_date = current_date
            self._submit_exit("expiration-date liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if self._exit_order_is_open():
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(
            "Exit submitted: {0}; reason: {1}.".format(
                self.held_symbol,
                reason,
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.PartiallyFilled,
                    OrderStatus.Filled,
                ):
                    if self.held_symbol is None:
                        self.held_symbol = order_event.Symbol
                        self.entry_price = float(order_event.FillPrice)
                        self.Debug(
                            "Entry filled: {0} at {1}.".format(
                                self.held_symbol,
                                self.entry_price,
                            )
                        )

                if order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.entry_ticket = None
                    self.Debug("Entry order did not fill.")

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                    OrderStatus.Filled,
                ):
                    if (
                        self.held_symbol is not None
                        and self.Portfolio[self.held_symbol].Quantity == 0
                    ):
                        self.Debug(
                            "Option position exited: {0}.".format(
                                self.held_symbol
                            )
                        )
                        self.held_symbol = None
                        self.entry_price = None
                        self.exit_ticket = None

        if order_event.Symbol == self.spy.Symbol and order_event.FillQuantity != 0:
            self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity == 0:
            self.equity_liquidation_ticket = None
            return

        if (
            self.equity_liquidation_ticket is not None
            and self.equity_liquidation_ticket.Status
            not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
                OrderStatus.Filled,
            )
        ):
            return

        self.Debug(
            "Unexpected SPY exercise or assignment position detected: {0} shares.".format(
                quantity
            )
        )
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy.Symbol,
            -quantity,
        )
        self.Debug("Unexpected SPY position liquidation submitted.")

    def _has_option_holding(self):
        return (
            self.held_symbol is not None
            and self.held_symbol in self.Portfolio
            and self.Portfolio[self.held_symbol].Quantity != 0
        )

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
            while candidate.weekday() >= 5:
                candidate -= timedelta(days=1)

        return candidate.granted or candidate

    def OnEndOfAlgorithm(self):
        if self._has_option_holding():
            self.Debug("Unexpected option holding remains at algorithm end.")

