from datetime import datetime, timedelta, time


class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self._minute_bucket_date = None
        self._bucket_end = None
        self._bucket_bars = {}

        self._closes = []
        self._previous_fast = None
        self._previous_slow = None

        self._entry_order_id = None
        self._held_symbol = None
        self._entry_fill_price = None
        self._exit_ticket = None
        self._time_stop_submitted = False
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Immediately liquidate equity created by exercise or assignment.
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested and spy_holding.Quantity != 0:
            self.Debug(
                "Unexpected SPY exercise or assignment detected; liquidating equity."
            )
            self._blocked_entry_date = current_date
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

        # Exits are evaluated on every minute Slice.
        if self._held_symbol is not None:
            self._process_expiration_and_time_stop()
            self._process_profit_target(slice)

        # Build and process any completed five-minute SPY bar in this Slice.
        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = minute_bar.EndTime
        bar_date = local_end.date()
        bar_time = local_end.time()

        if bar_time <= time(9, 30) or bar_time > time(16, 0):
            return

        if self._minute_bucket_date != bar_date:
            self._minute_bucket_date = bar_date
            self._bucket_end = None
            self._bucket_bars = {}

        minutes_since_0930 = (
            local_end - datetime.combine(bar_date, time(9, 30))
        ).total_seconds() // 60

        bucket_number = int((minutes_since_0930 - 1) // 5)
        bucket_end = datetime.combine(
            bar_date,
            time(9, 35)
        ) + timedelta(minutes=5 * bucket_number)

        if self._bucket_end is not None and bucket_end != self._bucket_end:
            self._bucket_bars = {}

        self._bucket_end = bucket_end
        self._bucket_bars[local_end] = minute_bar

        if local_end != bucket_end or len(self._bucket_bars) != 5:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)
        ]
        if any(expected not in self._bucket_bars for expected in expected_times):
            self._bucket_bars = {}
            return

        close = minute_bar.Close
        self._bucket_bars = {}
        self._process_five_minute_close(close, bucket_end, slice)

    def _process_five_minute_close(self, close, bar_end, slice: Slice):
        self._closes.append(float(close))
        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        fast = sum(self._closes[-5:]) / 5.0
        slow = sum(self._closes[-20:]) / 20.0

        bullish_crossover = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if not bullish_crossover:
            return

        end_time = bar_end.time()
        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        if (
            self._held_symbol is not None
            or self._entry_order_id is not None
            or self._blocked_entry_date == self.Time.date()
        ):
            return

        self._try_enter(slice, float(close))

    def _try_enter(self, slice: Slice, spy_price: float):
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        candidates = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying expiration or call contract."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self._entry_order_id = None
        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish MA crossover")
        if ticket is not None:
            self._entry_order_id = ticket.OrderId
            self.Debug(
                "Entry submitted: {} expiration {} strike {}.".format(
                    selected.Symbol,
                    selected.Expiry.date(),
                    selected.Strike
                )
            )

    def _process_profit_target(self, slice: Slice):
        if (
            self._held_symbol is None
            or self._entry_fill_price is None
            or self._exit_ticket is not None
        ):
            return

        held_contract = None
        for chain in slice.OptionChains.Values:
            held_contract = chain.Contracts.get(self._held_symbol)
            if held_contract is not None:
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self._entry_fill_price:
            return

        self._cancel_open_exit_order()
        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(
                self._held_symbol,
                -quantity,
                tag="50 percent profit target"
            )
            self.Debug(
                "Profit-target exit submitted for {} at midpoint {:.2f}.".format(
                    self._held_symbol,
                    midpoint
                )
            )

    def _process_expiration_and_time_stop(self):
        if self._held_symbol is None:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self._blocked_entry_date = current_date
            if self._exit_ticket is None:
                quantity = self.Portfolio[self._held_symbol].Quantity
                if quantity != 0:
                    self._exit_ticket = self.MarketOrder(
                        self._held_symbol,
                        -quantity,
                        tag="Expiration protection"
                    )
                    self.Debug(
                        "Expiration-protection exit submitted for {}.".format(
                            self._held_symbol
