                    )
            return

        previous_trading_day = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        while not exchange_hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
            and not self._time_stop_submitted
        ):
            self._blocked_entry_date = expiry_date
            if self._exit_ticket is None:
                quantity = self.Portfolio[self._held_symbol].Quantity
                if quantity != 0:
                    self._exit_ticket = self.MarketOrder(
                        self._held_symbol,
                        -quantity,
                        tag="Pre-expiration time stop"
                    )
                    self._time_stop_submitted = True
                    self.Debug(
                        "Pre-expiration time-stop submitted for {}.".format(
                            self._held_symbol
                        )
                    )

    def _cancel_open_exit_order(self):
        if self._exit_ticket is None:
            return

        status = self._exit_ticket.Status
        if status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ):
            self._exit_ticket.Cancel("Profit target superseded prior exit")
        self._exit_ticket = None

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected option exercise or assignment: {}.".format(
                    order_event.Symbol
                )
            )
            self._blocked_entry_date = self.Time.date()
            if self.Portfolio[self.spy].Invested:
                self.Liquidate(
                    self.spy,
                    "Unexpected option exercise or assignment"
                )

        if (
            self._entry_order_id is not None
            and order_event.OrderId == self._entry_order_id
        ):
            if (
                order_event.Status in
                (OrderStatus.PartiallyFilled, OrderStatus.Filled)
                and order_event.FillQuantity > 0
            ):
                self._held_symbol = order_event.Symbol
                self._entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}.".format(
                        order_event.Symbol,
                        self._entry_fill_price
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_order_id = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            if order_event.Status == OrderStatus.Filled:
