from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.closes = deque(maxlen=20)
        self.pending_signal = False
        self.pending_signal_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Handle unexpected SPY exercise or assignment.
        equity_quantity = self.Portfolio[self.spy_symbol].Quantity
        if equity_quantity != 0:
            self.Debug(
                f"Unexpected SPY exercise/assignment handling: "
                f"liquidating {equity_quantity} shares"
            )
            self.MarketOrder(
                self.spy_symbol,
                -equity_quantity,
                tag="Unexpected exercise or assignment"
            )
            self.no_entry_date = current_date

        # Feed only actual minute bars to the five-minute consolidator.
        minute_bar = slice.Bars.get(self.spy_symbol)
        if minute_bar is not None:
            self.consolidator.Update(minute_bar)

        # Never intentionally hold through expiration.
        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if current_date >= expiration_date:
                self.SubmitExit("Expiration liquidation")
            elif self.IsExpirationEve(current_date, expiration_date):
                if self.Time.hour == 15 and self.Time.minute == 45:
                    self.SubmitExit("Expiration-eve time stop")
            else:
                self.CheckProfitTarget(slice)

        # Evaluate a new signal immediately after the consolidated bar closes.
        if self.pending_signal:
            signal_price = self.pending_signal_price
            self.pending_signal = False
            self.pending_signal_price = None

            if (
                self.entry_ticket is None
                and self.held_option is None
                and current_date != self.no_entry_date
            ):
                self.TryEnter(slice, signal_price)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_values = list(self.closes)
            previous_fast = sum(previous_values[-5:]) / 5.0
            previous_slow = sum(previous_values) / 20.0

        self.closes.append(float(bar.Close))

        if len(self.closes) < 20 or previous_fast is None:
            return

        current_values = list(self.closes)
        current_fast = sum(current_values[-5:]) / 5.0
        current_slow = sum(current_values) / 20.0

        bar_time = bar.EndTime.time()
        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        if (
            eligible_start <= bar_time <= eligible_end
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal = True
            self.pending_signal_price = float(bar.Close)

    def TryEnter(self, slice: Slice, spy_price: float):
        chain = None
        chains = slice.OptionChains

        try:
            chain = chains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: current Slice has no SPY option chain")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        eligible_contracts = []
        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue

            expiration_date = contract.Expiry.date()
            if expiration_date < minimum_expiration:
                continue

            eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        minimum_strike = spy_price * 1.01
        strike_candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiration
            and contract.Strike >= minimum_strike
        ]

        if not strike_candidates:
            self.Debug(
                "Skipped entry: no call strike is at least 1% out of the money"
            )
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={nearest_expiration} strike={selected.Strike}"
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        contract = None
        chain = None

        try:
            chain = slice.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is not None:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option} ({reason})")

    def IsOrderOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def IsExpirationEve(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while candidate.weekday() >= 5 or not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time(0, 0))
        ):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.FillQuantity > 0:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {self.held_option} "
                        f"price={self.entry_price}"
                    )

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    if order_event.Status != OrderStatus.Filled:
                        self.Debug(
                            f"Entry order {order_event.Status}: "
                            f"{order_event.Symbol}"
                        )
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {order_event.Symbol}")
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

