        self.option.SetFilter(-1000, 1000, 0, 730)
        self.option_symbol = self.option.Symbol

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_date = None
        self.minute_bucket_end = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None
        self.latest_spy_price = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self.ProcessExpiration
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.ProcessTimeStop
        )

    def OnData(self, slice: Slice):
        self.latest_spy_price = None

        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]
            self.latest_spy_price = spy_bar.Close
            self.ProcessMinuteBar(spy_bar)

        self.HandleUnexpectedEquityPosition()

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self.ProcessProfitTarget(slice)

        if getattr(self, "pending_signal", False):
            self.pending_signal = False
            self.TryEnter(slice)

    def ProcessMinuteBar(self, bar: TradeBar):
        end_time = bar.EndTime
        session_start = datetime.combine(end_time.date(), time(9, 30))
        session_end = datetime.combine(end_time.date(), time(16, 0))

        if end_time <= session_start or end_time > session_end:
            return

        minute_offset = int((end_time - session_start).total_seconds() // 60)
        bucket_number = (minute_offset + 4) // 5
        bucket_end = session_start + timedelta(minutes=bucket_number * 5)

        if self.minute_bucket_date != end_time.date() or self.minute_bucket_end != bucket_end:
            if self.minute_bucket_end is not None:
                self.EmitCompletedFiveMinuteBar()

            self.minute_bucket_date = end_time.date()
            self.minute_bucket_end = bucket_end
            self.minute_bars = {}

        self.minute_bars[end_time] = bar

        if end_time == bucket_end:
            self.EmitCompletedFiveMinuteBar()

    def EmitCompletedFiveMinuteBar(self):
        if self.minute_bucket_end is None:
            return

        expected_times = [
            self.minute_bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.minute_bars for t in expected_times):
            self.minute_bars = {}
            return

        bars = [self.minute_bars[t] for t in expected_times]

        consolidated = TradeBar(
            self.minute_bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self.OnFiveMinuteBar(consolidated)
        self.minute_bars = {}

    def OnFiveMinuteBar(self, bar: TradeBar):
        self.fast_window.append(bar.Close)
        self.slow_window.append(bar.Close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        fast = sum(self.fast_window) / 5.0
        slow = sum(self.slow_window) / 20.0

        if self.previous_fast is not None and self.previous_slow is not None:
            eligible_time = time(9, 45) <= bar.EndTime.time() <= time(14, 30)

            if (
                eligible_time
                and self.previous_fast <= self.previous_slow
                and fast > slow
            ):
                self.pending_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def TryEnter(self, slice: Slice):
        if self.expiration_block_date == self.Time.date():
            return

        if self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket):
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * self.latest_spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                self.entry_symbol, selected_expiry, selected.Strike
            )
        )

    def ProcessProfitTarget(self, slice: Slice):
        if self.entry_symbol is None or not self.Portfolio[self.entry_symbol].Invested:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        quote = self.GetHeldOptionQuote(slice)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def ProcessTimeStop(self):
        if self.entry_symbol is None or not self.Portfolio[self.entry_symbol].Invested:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        previous_trading_day = self.GetPreviousTradingDay(expiry_date)

        if self.Time.date() == previous_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitExit("time stop")

    def ProcessExpiration(self):
        self.expiration_block_date = None

        if self.entry_symbol is None:
            return

        expiry_date = self.entry_symbol.ID.Date.date()

        if expiry_date <= self.Time.date():
            self.expiration_block_date = self.Time.date()

            if self.Portfolio[self.entry_symbol].Invested:
                self.SubmitExit("expiration protection")

    def SubmitExit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {0} ({1})".format(self.entry_symbol, reason))

    def GetHeldOptionQuote(self, slice: Slice):
        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(self.entry_symbol):
                contract = chain.Contracts[self.entry_symbol]
                return contract.BidPrice, contract.AskPrice

        if slice.QuoteBars.ContainsKey(self.entry_symbol):
            quote = slice.QuoteBars[self.entry_symbol]
            bid = quote.Bid.Close if quote.Bid is not None else 0
            ask = quote.Ask.Close if quote.Ask is not None else 0
            return bid, ask

        return None

    def GetPreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def HandleUnexpectedEquityPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.expiration_block_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self.MarketOrder(self.spy, -quantity)

    def OnAssignmentOrderEvent(self, assignment_event):
        self.expiration_block_date = self.Time.date()
        self.Debug("Unexpected option assignment or exercise received.")
        self.HandleUnexpectedEquityPosition()

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.entry_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        self.entry_symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

