from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = None

        self.active_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_dates = set()
        self.exercise_logged_dates = set()

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, self.consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        current_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
        current_slow = float(self.slow.Current.Value) if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            current_fast is not None
            and current_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
        ):
            crossover = (
                current_fast <= current_slow
                and float(self.fast.Current.Value) > float(self.slow.Current.Value)
            )

            end_time = bar.EndTime
            if (
                crossover
                and end_time.time() >= self.TimeOfDay(9, 45)
                and end_time.time() <= self.TimeOfDay(14, 30)
            ):
                self.pending_entry_signal = end_time

        self.previous_fast = float(self.fast.Current.Value)
        self.previous_slow = float(self.slow.Current.Value)

    def OnData(self, slice):
        today = self.Time.date()

        if self.Portfolio[self.spy.Symbol].Invested:
            if today not in self.exercise_logged_dates:
                self.Debug(
                    f"Unexpected SPY equity position detected on {today}; liquidating."
                )
                self.exercise_logged_dates.add(today)
            self.MarketOrder(
                self.spy.Symbol,
                -self.Portfolio[self.spy.Symbol].Quantity
            )
            self.no_entry_dates.add(today)

        if self.active_option is not None:
            expiry_date = self.active_option.Expiry.date()

            if today >= expiry_date:
                self.no_entry_dates.add(today)
                self.SubmitExpirationExit()

            elif (
                today == self.PrecedingTradingDate(expiry_date)
                and self.TimeOfDay(15, 45) <= self.Time.time()
            ):
                self.SubmitExpirationExit()

            elif self.entry_price is not None and self.HasInvestedOption():
                quote = self.GetCurrentOptionQuote(slice, self.active_option.Symbol)
                if quote is not None:
                    bid, ask = quote
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.5 * self.entry_price:
                        self.SubmitProfitExit(midpoint)

        if self.pending_entry_signal is not None:
            signal_time = self.pending_entry_signal
            self.pending_entry_signal = None

            if today in self.no_entry_dates:
                return

            if (
                self.active_option is not None
                or self.HasInvestedOption()
                or self.IsEntryOrderOpen()
            ):
                return

            self.TryEnterFromCurrentChain(slice, signal_time)

    def TryEnterFromCurrentChain(self, slice, signal_time):
        if not slice.OptionChains:
            self.Debug(f"Skipped option selection at {signal_time}: no option chain.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)
        current_price = float(self.Securities[self.spy.Symbol].Price)

        if current_price <= 0:
            self.Debug(f"Skipped option selection at {signal_time}: invalid SPY price.")
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug(
                f"Skipped option selection at {signal_time}: "
                "no qualifying expiration or call contract."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = 1.01 * current_price

        candidates = [
            contract for contract in contracts
            if (
                contract.Expiry.date() == nearest_expiry
                and float(contract.Strike) >= minimum_strike
            )
        ]

        if not candidates:
