                    order_event.OrderId == self.entry_ticket.OrderId and
                    order_event.Status in (OrderStatus.PartiallyFilled,
                                           OrderStatus.Filled)):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )

            if (self.exit_ticket is not None and
                    order_event.OrderId == self.exit_ticket.OrderId and
                    order_event.Status in (OrderStatus.PartiallyFilled,
                                           OrderStatus.Filled)):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {}".format(order_event.Symbol))
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_symbol = None
                    self.entry_price = None

    def _update_five_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return None

        minute_bar = slice.Bars[self.spy]
        end = minute_bar.EndTime.replace(second=0, microsecond=0)

        if not (end.hour > 9 or (end.hour == 9 and end.minute >= 31)):
            return None
        if end.hour > 16 or (end.hour == 16 and end.minute > 0):
            return None

        minutes_from_open = (end.hour * 60 + end.minute) - (9 * 60 + 30)
        bucket_end_minute = 30 + ((minutes_from_open + 4) // 5) * 5
        bucket_end = end.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60
        )

        completed = None

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            completed = self._complete_bucket()
            self.bucket_bars = []
            self.bucket_valid = True

        if self.bucket_end != bucket_end:
            self.bucket_date = end.date()
            self.bucket_end = bucket_end
            self.bucket_bars = []
            self.bucket_valid = True

        if self.bucket_bars:
            previous_end = self.bucket_bars[-1].EndTime.replace(
                second=0, microsecond=0
            )
            if end - previous_end != timedelta(minutes=1):
                self.bucket_valid = False

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) > 5:
            self.bucket_valid = False

        if bucket_end.hour == 16 and bucket_end.minute == 0:
            completed = self._complete_bucket()
            self.bucket_bars = []
            self.bucket_end = None
            self.bucket_valid = True

        return completed

    def _complete_bucket(self):
        if not self.bucket_valid or len(self.bucket_bars) != 5:
            return None

        close = self.bucket_bars[-1].Close
        self.fast_window.append(close)
        self.slow_window.append(close)

        result = {
            "end": self.bucket_end,
            "close": close
        }

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            self.previous_fast = None
            self.previous_slow = None
        else:
            self.previous_fast = (
                sum(self.fast_window) / len(self.fast_window)
                if self.previous_fast is None else self.previous_fast
            )
            self.previous_slow = (
                sum(self.slow_window) / len(self.slow_window)
                if self.previous_slow is None else self.previous_slow
            )

        return result

    def _try_enter(self, slice: Slice, spy_price: float):
        if spy_price <= 0 or not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiration_date = contract.Symbol.ID.Date.date()
                if expiration_date >= minimum_expiration:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        nearest_expiration = min(
            contract.Symbol.ID.Date.date() for contract in contracts
        )

        eligible = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == nearest_expiration
            and contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible call contract.")
            return

        selected = min(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _process_held_option(self, slice: Slice):
        symbol = self.held_symbol
        expiration_date = symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration_date:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)

        if (current_date == previous_trading_day and
                self.Time.hour == 15 and self.Time.minute >= 45):
            self._submit_exit("expiration time stop")
            return

        if self.entry_price is None or self.exit_ticket is not None:
            return

        quote = self._find_option_quote(slice, symbol)
        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _find_option_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            return

        for ticket in self.Transactions.GetOpenOrderTickets():
            if ticket.Symbol == self.held_symbol:
                ticket.Cancel("Replacing open exit order")

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def _entry_order_open(self):
        return self.entry_ticket is not None and self._ticket_open(self.entry_ticket)

    def _ticket_open(self, ticket):
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.spy_security.Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

