from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, True, 0, True)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA, True)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = RollingWindow[float](self.fast_period)
        self.slow_values = RollingWindow[float](self.slow_period)

        self.minute_groups = {}
        self.held_symbol = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.expiration_block_date = None
        self.time_stop_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)
        self._check_time_stop(current_date, slice)
        self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        consolidated = self._consolidate_minute_bar(spy_bar)
        if consolidated is None:
            return

        close = float(consolidated.Close)
        self.fast_values.Add(close)
        self.slow_values.Add(close)

        if not (self.fast_values.IsReady and self.slow_values.IsReady):
            return

        if self.held_symbol is not None or self.entry_order_id is not None:
            return

        end_time = consolidated.EndTime
        if end_time.date() != current_date:
            return

        if not (end_time.hour == 9 and end_time.minute >= 45) and not (
            end_time.hour > 9 and end_time.hour < 14
        ) and not (end_time.hour == 14 and end_time.minute <= 30):
            return

        previous_fast = self.fast_values[1]
        previous_slow = self.slow_values[1]
        current_fast = self.fast_values[0]
        current_slow = self.slow_values[0]

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )
        if not bullish_cross:
            return

        self._try_enter(slice, current_date, close)

    def _consolidate_minute_bar(self, bar: TradeBar):
        bar_time = bar.Time
        if bar_time.date() != self.Time.date():
            return None

        if bar_time.hour < 9 or bar_time.hour > 15:
            return None
        if bar_time.hour == 9 and bar_time.minute < 30:
            return None

        minute_of_day = bar_time.hour * 60 + bar_time.minute
        session_start = 9 * 60 + 30
        offset = minute_of_day - session_start
        slot_start = session_start + (offset // 5) * 5
        slot_end = slot_start + 4

        key = (bar_time.date(), slot_start)
        group = self.minute_groups.setdefault(key, {})

        group[bar_time] = bar

        if minute_of_day != slot_end:
            return None

        expected_times = [
            datetime(
                bar_time.year,
                bar_time.month,
                bar_time.day,
                (slot_start + i) // 60,
                (slot_start + i) % 60,
            )
            for i in range(5)
        ]

        if any(t not in group for t in expected_times):
            self.minute_groups.pop(key, None)
            return None

        bars = [group[t] for t in expected_times]
        self.minute_groups.pop(key, None)

        return TradeBar(
            Symbol=self.spy.Symbol,
            Time=bars[0].Time,
            Period=timedelta(minutes=5),
            Open=bars[0].Open,
            High=max(b.High for b in bars),
            Low=min(b.Low for b in bars),
            Close=bars[-1].Close,
            Volume=sum(b.Volume for b in bars),
        )

    def _try_enter(self, slice: Slice, current_date, spy_price):
        if self.expiration_block_date == current_date:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible = []
        for contract in chain:
            expiry = contract.Expiry.date()
            if expiry < current_date + timedelta(days=7):
                continue
            if contract.Right != OptionRight.Call:
                continue
            if contract.Strike < 1.01 * spy_price:
                continue
            eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no eligible option contract.")
            return

        nearest_expiry = min(c.Expiry.date() for c in eligible)
        selected = sorted(
            [c for c in eligible if c.Expiry.date() == nearest_expiry],
            key=lambda c: (c.Strike, str(c.Symbol)),
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug("Entry submitted: " + str(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return
        if self.exit_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = None
        for candidate in chain:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        self._cancel_open_exit_order()
        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_symbol, -quantity)
            if ticket is not None:
                self.exit_order_id = ticket.OrderId
                self.Debug("Profit-target exit submitted: " + str(self.held_symbol))

    def _check_time_stop(self, current_date, slice: Slice):
        if self.held_symbol is None or self.exit_order_id is not None:
            return
        if self.time_stop_submitted:
            return
        if self.Time.hour < 15 or (self.Time.hour == 15 and self.Time.minute < 45):
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        prior_trading_day = self._previous_trading_day(expiry)
        if current_date != prior_trading_day:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_symbol, -quantity)
            if ticket is not None:
                self.exit_order_id = ticket.OrderId
                self.time_stop_submitted = True
                self.Debug("Time-stop exit submitted: " + str(self.held_symbol))

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date < expiry:
            return

        self.expiration_block_date = current_date
        if self.exit_order_id is None:
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0:
                ticket = self.MarketOrder(self.held_symbol, -quantity)
                if ticket is not None:
                    self.exit_order_id = ticket.OrderId
                    self.Debug("Expiration exit submitted: " + str(self.held_symbol))

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while True:
            try:
                is_open = hours.IsDateOpen(
                    datetime(candidate.year, candidate.month, candidate.day)
                )
            except Exception:
                is_open = candidate.weekday() < 5

            if is_open:
                return candidate
            candidate -= timedelta(days=1)

    def _cancel_open_exit_order(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None and ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ]:
            ticket.Cancel("Replaced by profit-target liquidation")
        self.exit_order_id = None

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_order_id is not None
                and order_event.OrderId == self.entry_order_id
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.time_stop_submitted = False
                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )

            elif (
                self.exit_order_id is not None
                and order_event.OrderId == self.exit_order_id
            ):
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None
                self.time_stop_submitted = False

        if order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled,
        ] and self.entry_order_id == order_event.OrderId:
            if order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None

        assignment = bool(getattr(order_event, "IsAssignment", False))
        exercise = bool(getattr(order_event, "IsExercise", False))

        if assignment or exercise:
            self.Debug("Unexpected exercise or assignment handling.")
            equity_quantity = self.Portfolio[self.spy.Symbol].Quantity
            if equity_quantity != 0:
                self.MarketOrder(self.spy.Symbol, -equity_quantity)
                self.Debug("Liquidated unexpected SPY equity position.")

