                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None
                self.time_stop_submitted = False

        if order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled,
        ] and self.entry_order_id == order_event.OrderId:
            if order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None

        assignment = bool(getattr(order_event, "IsAssignment", False))
        exercise = bool(getattr(order_event, "IsExercise", False))

        if assignment or exercise:
            self.Debug("Unexpected exercise or assignment handling.")
            equity_quantity = self.Portfolio[self.spy.Symbol].Quantity
            if equity_quantity != 0:
                self.MarketOrder(self.spy.Symbol, -equity_quantity)
                self.Debug("Liquidated unexpected SPY equity position.")

