from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self._bucket_start = None
        self._bucket_bars = []

        self._closes = deque(maxlen=20)
        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._no_entry_date = None
        self._equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position()

        if self._held_symbol is not None:
            if today >= self._held_symbol.ID.Date.date():
                self._no_entry_date = today
                self._submit_exit("expiration protection")
            elif (
                today == self._held_symbol.ID.Date.date() - timedelta(days=1)
                and now.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")
            else:
                self._check_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        bar_start = bar.Time
        local_date = bar_start.date()

        if not self._is_regular_session_minute(bar_start):
            return

        if self._bucket_start is None or local_date != self._bucket_start.date():
            self._bucket_start = self._five_minute_bucket_start(bar_start)
            self._bucket_bars = [bar]
            return

        bucket_start = self._five_minute_bucket_start(bar_start)

        if bucket_start != self._bucket_start:
            completed_bars = self._bucket_bars
            completed_start = self._bucket_start

            self._bucket_start = bucket_start
            self._bucket_bars = [bar]

            if len(completed_bars) == 5:
                self._on_five_minute_bar(
                    completed_bars[-1].Close,
                    completed_start + timedelta(minutes=5),
                    slice
                )
            return

        if len(self._bucket_bars) < 5:
            self._bucket_bars.append(bar)

    def _on_five_minute_bar(self, close, end_time, slice):
        previous_fast = None
        previous_slow = None

        if len(self._closes) >= 5:
            previous_fast = sum(list(self._closes)[-5:]) / 5.0
        if len(self._closes) >= 20:
            previous_slow = sum(self._closes) / 20.0

        self._closes.append(float(close))

        if len(self._closes) < 20:
            return

        current_fast = sum(list(self._closes)[-5:]) / 5.0
        current_slow = sum(self._closes) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover:
            return

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        if self._can_submit_entry():
            self._try_enter(slice, float(close), end_time.date())

    def _try_enter(self, slice, spy_price, algorithm_date):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiration = algorithm_date + timedelta(days=7)
        eligible = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol

                if contract.Right != OptionRight.Call:
                    continue
                if symbol.ID.Date.date() < minimum_expiration:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue

                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no eligible option contract.")
            return

        nearest_expiration = min(
            contract.Symbol.ID.Date.date() for contract in eligible
        )
        eligible = [
            contract for contract in eligible
            if contract.Symbol.ID.Date.date() == nearest_expiration
        ]

        lowest_strike = min(contract.Strike for contract in eligible)
        eligible = [
            contract for contract in eligible
            if contract.Strike == lowest_strike
        ]

        selected = min(eligible, key=lambda contract: str(contract.Symbol))
        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish crossover entry"
        )

    def _check_profit_target(self, slice):
        if self._entry_price is None or self._exit_ticket_is_open():
            return

        contract = None
        for chain in slice.OptionChains.Values:
            if self._held_symbol in chain.Contracts:
                contract = chain.Contracts[self._held_symbol]
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_ticket_is_open():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None:
            self._exit_ticket.Cancel("replace with liquidation order")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Symbol == self.spy and order_event.FillQuantity != 0:
            self.Debug("Unexpected SPY exercise/assignment handling.")
            return

        if order.Tag == "bullish crossover entry":
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ) and order_event.FillQuantity > 0:
                self._held_symbol = order.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None
                self.Debug(
                    "Entry filled: " + str(order.Symbol) +
                    " at " + str(self._entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None
                self.Debug("Entry order canceled or invalid.")

        elif self._exit_ticket is not None and order.Id == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: " + str(order.Symbol))
                self._held_symbol = None
                self._entry_price = None
                self._exit_ticket = None

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy].Quantity

        if holding != 0:
            if self._equity_liquidation_ticket is None:
                self.Debug("Unexpected SPY position; liquidating immediately.")
                self._equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -holding,
                    tag="unexpected exercise or assignment liquidation"
                )
            return

        if self._equity_liquidation_ticket is not None:
            if self._equity_liquidation_ticket.Status not in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self._equity_liquidation_ticket = None

    def _can_submit_entry(self):
        if self._held_symbol is not None:
            return False

        if self._entry_ticket is not None and self._entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return False

        if self.Portfolio[self.spy].Quantity != 0:
            return False

        if self._equity_liquidation_ticket is not None:
            return False

        if self._no_entry_date == self.Time.date():
            return False

        return True

    def _exit_ticket_is_open(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.Status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    @staticmethod
    def _is_regular_session_minute(moment):
        return (
            time(9, 30) <= moment.time() < time(16, 0)
            and moment.second == 0
        )

    @staticmethod
    def _five_minute_bucket_start(moment):
        session_start = datetime(
            moment.year, moment.month, moment.day, 9, 30
        )
        elapsed_minutes = int((moment - session_start).total_seconds() // 60)
        bucket_minute = (elapsed_minutes // 5) * 5
        return session_start + timedelta(minutes=bucket_minute)

