from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteOptionCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option = option.Symbol

        self.closes = deque(maxlen=20)
        self.current_bucket = None
        self.bucket_closes = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.no_entry_today = False
        self.last_seen_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.last_seen_date != today:
            self.last_seen_date = today
            self.no_entry_today = False

        # Handle unexpected SPY equity created by exercise or assignment.
        equity_quantity = self.Portfolio[self.spy].Quantity
        if equity_quantity != 0:
            self.Debug(
                "Unexpected exercise/assignment: liquidating SPY equity "
                f"position of {equity_quantity} shares."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.no_entry_today = True

        # Never intentionally hold an option into its expiration date.
        if self.held_contract is not None:
            expiry = self.held_contract.ID.Date.date()
            if today >= expiry:
                self.no_entry_today = True
                self._submit_exit("Expiration processing")

        # Manage the existing option position on every minute Slice.
        if self.held_contract is not None and self.entry_price is not None:
            if self._is_expiration_eve_trading_day(today):
                if self.Time.hour == 15 and self.Time.minute >= 45:
                    self._submit_exit("Expiration-eve time stop")
            else:
                quote = slice.QuoteBars.get(self.held_contract)
                if quote is not None:
                    bid = quote.Bid.Close
                    ask = quote.Ask.Close
                    if (
                        bid is not None and ask is not None
                        and bid > 0 and ask > 0
                    ):
                        midpoint = (bid + ask) / 2.0
                        if midpoint >= 1.5 * self.entry_price:
                            self._cancel_open_exit()
                            self._submit_exit("50% profit target")

        # Build aligned five-minute SPY bars from actual minute bars only.
        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        local_time = self.Time
        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 31
        ):
            return
        if local_time.hour > 16 or (
            local_time.hour == 16 and local_time.minute > 0
        ):
            return

        bucket_end_minute = ((local_time.minute + 4) // 5) * 5
        bucket = (
            local_time.date(),
            local_time.hour,
            bucket_end_minute
        )

        if self.current_bucket != bucket:
            self.current_bucket = bucket
            self.bucket_closes = []

        self.bucket_closes.append(bar.Close)

        # A regular-session five-minute bar ending at :35, :40, etc.
        if local_time.minute % 5 != 0:
            return

        if len(self.bucket_closes) != 5:
            self.bucket_closes = []
            return

        close = self.bucket_closes[-1]
        self.bucket_closes = []

        previous_fast = None
        previous_slow = None
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (9 <= local_time.hour <= 14):
            return
        if local_time.hour == 9 and local_time.minute < 45:
            return
        if local_time.hour == 14 and local_time.minute > 30:
            return

        self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.no_entry_today:
            return
