            if (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        expiration = min(contract.Expiry.date() for contract in eligible)
        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * self.Securities[self.spy].Price
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call contract met the expiration and strike rules."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

