        while check > date and not self._is_trading_day(check):
            check -= timedelta(days=1)

        return date == check

    def _is_trading_day(self, date):
        return self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(date.year, date.month, date.day)
        )

