from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=3650))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.held_option = None

        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        self._evaluate_open_position(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.EndTime
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if bar_clock < time(9, 30) or bar_clock > time(16, 0):
            return

        minute = bar_time.minute
        bucket_minute = ((minute + 4) // 5) * 5
        bucket_end = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bar_time.hour,
            0,
            0
        ) + timedelta(minutes=bucket_minute)

        bucket_key = (bar_date, bucket_end)

        if self.bucket_end is not None and bucket_key != (
            self.bucket_date,
            self.bucket_end
        ):
            self._complete_bucket()

        if self.bucket_end != bucket_end or self.bucket_date != bar_date:
            self.bucket_date = bar_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = minute_bar

        if bar_time == bucket_end:
            self._complete_bucket(slice)

    def _complete_bucket(self, slice: Slice = None):
        if self.bucket_end is None:
            return

        bars = list(self.bucket_bars.values())
        expected_minutes = {
            self.bucket_end - timedelta(minutes=i) for i in range(5)
        }
        actual_minutes = set(self.bucket_bars.keys())

        if len(bars) != 5 or actual_minutes != expected_minutes:
            self.bucket_date = None
            self.bucket_end = None
            self.bucket_bars = {}
            return

        bars.sort(key=lambda x: x.EndTime)
        consolidated_close = bars[-1].Close

        self.closes.append(float(consolidated_close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        current_fast = None
        current_slow = None

        if len(self.closes) >= self.fast_period:
            current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        if len(self.closes) >= self.slow_period:
            current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if bullish_cross and slice is not None:
            end_clock = self.bucket_end.time()
            if time(9, 45) <= end_clock <= time(14, 30):
                self._try_enter(slice, consolidated_close)

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

    def _try_enter(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()

        if self.expiration_block_date == current_date:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self._entry_order_open():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                expiry_date = contract.Expiry.date()
                if expiry_date >= current_date + timedelta(days=7):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * float(spy_price)
        ]

        if not eligible:
            self.Debug("Skipped entry: no qualifying contract at nearest expiration.")
            return

        eligible.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = eligible[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.held_option = selected.Symbol
        self.entry_price = None

    def _evaluate_open_position(self, slice: Slice):
        symbol = self.held_option
        if symbol is None:
            return

        holding = self.Portfolio[symbol]
        if not holding.Invested:
            return

        expiry_date = symbol.ID.Date.date()
        current_date = self.Time.date()
        current_clock = self.Time.time()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self._submit_option_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and current_clock >= time(15, 45)
        ):
            self._submit_option_exit("pre-expiration time stop")
            return

        quote = self._find_current_option_quote(slice, symbol)
        if quote is None:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50% profit target")

    def _find_current_option_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def _submit_option_exit(self, reason: str):
        symbol = self.held_option
        if symbol is None or not self.Portfolio[symbol].Invested:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_open(self.entry_ticket):
            return

        for ticket in self.Transactions.GetOpenOrderTickets():
            if ticket.Symbol == symbol and ticket.OrderId != (
                self.exit_ticket.OrderId if self.exit_ticket is not None else -1
            ):
                ticket.Cancel("Canceled before liquidation")

        quantity = -self.Portfolio[symbol].Quantity
        self.exit_ticket = self.MarketOrder(symbol, quantity, tag=reason)
        self.Debug("Submitted option exit: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered " + str(order_event.Symbol) +
                    " at " + str(self.entry_price)
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None
                self.held_option = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exited " + str(order_event.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment received.")
            self._liquidate_unexpected_equity()

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received.")
        self._liquidate_unexpected_equity()

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self._liquidate_unexpected_equity()

    def _liquidate_unexpected_equity(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None
            and self._ticket_open(self.equity_liquidation_ticket)
        ):
            return

        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _entry_order_open(self):
        return self.entry_ticket is not None and self._ticket_open(self.entry_ticket)

    def _ticket_open(self, ticket):
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if isinstance(candidate, datetime) else candidate

