from datetime import timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.current_group_date = None
        self.current_group_slot = None
        self.current_group_count = 0
        self.current_group_valid = True
        self.current_group_close = None

        self.entry_ticket = None
        self.held_option = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately remove any SPY equity created by unexpected exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY equity; "
                "liquidating the entire SPY position."
            )
            self.MarketOrder(self.spy, -spy_quantity, tag="Unexpected exercise/assignment")
            self.expiration_block_date = today
            return

        # Prevent entries on a day when expiration processing has already begun.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.expiration_block_date = today
                self._submit_exit("Expiration processing")
            elif (
                today == expiry_date - timedelta(days=1)
                and (self.Time.hour > 15 or
                     (self.Time.hour == 15 and self.Time.minute >= 45))
            ):
                self._submit_exit("Expiration time stop")

            if self.exit_ticket is None:
                self._check_profit_target(slice)

        if self.entry_ticket is not None and self.held_option is None:
            if self.entry_ticket.Status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.New
            ):
                pass

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 30
        ):
            return

        if local_time.hour > 16 or (
            local_time.hour == 16 and local_time.minute >= 0
        ):
            return

        minutes_from_open = (local_time.hour - 9) * 60 + local_time.minute - 30
        if minutes_from_open < 0:
            return

        slot = minutes_from_open // 5
        group_date = local_time.date()

        if (
            self.current_group_date is None
            or group_date != self.current_group_date
            or slot != self.current_group_slot
        ):
            self._finalize_five_minute_bar(slice)

            self.current_group_date = group_date
            self.current_group_slot = slot
            self.current_group_count = 0
            self.current_group_valid = True
            self.current_group_close = None

        expected_minute = 30 + slot * 5 + self.current_group_count
        expected_hour = 9 + expected_minute // 60
        expected_minute %= 60

        if local_time.hour != expected_hour or local_time.minute != expected_minute:
            self.current_group_valid = False

        self.current_group_count += 1
        self.current_group_close = minute_bar.Close

    def _finalize_five_minute_bar(self, slice: Slice):
        if (
            self.current_group_date is None
            or self.current_group_count != 5
            or not self.current_group_valid
            or self.current_group_close is None
        ):
            return

        close = float(self.current_group_close)
        current_fast = (
            sum(self.fast_values[-(self.fast_period - 1):]) + close
        ) / self.fast_period if len(self.fast_values) >= self.fast_period - 1 else None
        current_slow = (
            sum(self.slow_values[-(self.slow_period - 1):]) + close
        ) / self.slow_period if len(self.slow_values) >= self.slow_period - 1 else None

        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.fast_period:
            self.fast_values.pop(0)
        if len(self.slow_values) > self.slow_period:
            self.slow_values.pop(0)

        if len(self.fast_values) >= self.fast_period:
            current_fast = sum(self.fast_values[-self.fast_period:]) / self.fast_period
        else:
            current_fast = None

        if len(self.slow_values) >= self.slow_period:
            current_slow = sum(self.slow_values[-self.slow_period:]) / self.slow_period
        else:
            current_slow = None

        bar_end_hour = 9 + ((self.current_group_slot + 1) * 5) // 60
        bar_end_minute = ((self.current_group_slot + 1) * 5) % 60

        eligible_time = (
            (bar_end_hour > 9 or bar_end_minute >= 45)
            and (
                bar_end_hour < 14
                or (bar_end_hour == 14 and bar_end_minute <= 30)
            )
        )

        crossover = (
            prior_fast is not None
            and prior_slow is not None
            and current_fast is not None
            and current_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if (
            crossover
            and eligible_time
            and self.held_option is None
            and self.entry_ticket is None
            and self.expiration_block_date != self.Time.date()
        ):
            self._evaluate_entry(slice, close)

    def _evaluate_entry(self, slice: Slice, spy_price: float):
        chains = self._get_option_chains(slice)
        if not chains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= 1.01 * spy_price
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying option contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        contracts.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = contracts[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        contract = self._find_contract(slice, self.held_option.Symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.New
        ):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {:.4f}".format(
                    order_event.Symbol,
                    float(order_event.FillPrice)
                ))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.exit_ticket = None

        message = str(order_event.Message).lower()
        if "exercise" in message or "assignment" in message:
            self.Debug("Unexpected exercise or assignment event received.")

    def _get_option_chains(self, slice: Slice):
        result = []
        try:
            for chain in slice.OptionChains.Values:
                result.append(chain)
        except Exception:
            try:
                for chain in slice.OptionChains:
                    result.append(chain)
            except Exception:
                pass
        return result

    def _find_contract(self, slice: Slice, symbol: Symbol):
        for chain in self._get_option_chains(slice):
            for contract in chain.Contracts.Values:
                if contract.Symbol == symbol:
                    return contract
        return None	gbc

