        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        contracts.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = contracts[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        contract = self._find_contract(slice, self.held_option.Symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

