from AlgorithmImports import *
from datetime import timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._previous_fast = None
        self._previous_slow = None
        self._last_consolidated_end = None
        self._pending_signal = None

        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._held_expiry = None
        self._exit_ticket = None

        self._equity_warning_logged = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        end_time = bar.EndTime
        start_time = bar.Time

        if end_time.hour < 9 or end_time.hour > 16:
            return

        if end_time.hour == 9 and end_time.minute < 35:
            return

        if end_time.hour == 16 and end_time.minute > 0:
            return

        if end_time.minute % 5 != 0:
            return

        # Reject bars that span a missing five-minute interval.
        if end_time - start_time != timedelta(minutes=5):
            self._last_consolidated_end = end_time
            return

        if (
            self._last_consolidated_end is not None
            and end_time - self._last_consolidated_end != timedelta(minutes=5)
        ):
            self._last_consolidated_end = end_time
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, bar.Close)
        self.slow.Update(end_time, bar.Close)

        self._last_consolidated_end = end_time

        if previous_fast is None or previous_slow is None:
            return

        if (
            self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
            and (
