                or (end_time.hour == 9 and end_time.minute >= 45)
            )
            and (
                end_time.hour < 14
                or (end_time.hour == 14 and end_time.minute <= 30)
            )
        ):
            self._pending_signal = end_time

    def OnData(self, slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(current_date)

        if self._held_symbol is not None:
            self._evaluate_exit(slice, current_date)

        if self._pending_signal is not None:
            signal_time = self._pending_signal
            self._pending_signal = None

            if signal_time.date() != current_date:
                return

            self._evaluate_entry(slice, current_date)

