            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_exit(self, slice, current_date):
        if self._held_symbol is None or self._exit_order_is_open():
            return

        if self._held_expiry is not None:
            prior_trading_day = self._previous_trading_day(self._held_expiry)

            if (
                current_date == prior_trading_day
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("Expiration-eve time stop")
                return

        if self.option.Symbol not in slice.OptionChains:
            return

        chain = slice.OptionChains[self.option.Symbol]
        held_contract = next(
            (contract for contract in chain
             if contract.Symbol == self._held_symbol),
            None
        )

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self._entry_price is not None
            and midpoint >= 1.50 * self._entry_price
        ):
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        self._cancel_open_exit_order()

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0}, quantity {1}, reason: {2}".format(
                self._held_symbol, quantity, reason
            )
        )

    def _handle_expiration_processing(self, current_date):
        if self._held_expiry is None:
            return

        if current_date >= self._held_expiry:
            self._blocked_entry_date = current_date

            if self.Portfolio[self._held_symbol].Quantity != 0:
                self._submit_exit("Expiration processing liquidation")
                self.Debug(
                    "Expiration processing: liquidating {0}.".format(
                        self._held_symbol
                    )
                )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            if not self._equity_warning_logged:
                self.Debug(
                    "Unexpected exercise or assignment: liquidating SPY equity."
                )
                self._equity_warning_logged = True

            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
        else:
            self._equity_warning_logged = False

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _exit_order_is_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]

    def _cancel_open_exit_order(self):
        if self._exit_order_is_open():
            self._exit_ticket.Cancel("Replacing open exit order")

    def OnOrderEvent(self, order_event):
        if (
            getattr(order_event, "IsAssignment", False)
            or order_event.OrderType == OrderType.OptionExercise
        ):
            self.Debug(
                "Unexpected exercise or assignment event for {0}.".format(
                    order_event.Symbol
                )
            )
            self._blocked_entry_date = self.Time.date()

        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._held_expiry = self.Securities[
                    self._held_symbol
                ].Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: {0} at {1}.".format(
                        self._held_symbol, self._entry_price
                    )
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}.".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self._held_symbol = None
                self._entry_price = None
                self._held_expiry = None
                self._exit_ticket = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self._exit_ticket = None

