        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.spy_option = option.Symbol

        self._five_minute_bars = defaultdict(dict)
        self._closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None

        self._entry_ticket = None
        self._entry_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_assignment()
        self._process_expiration(current_date)
        self._evaluate_open_position(slice, current_date)

        if self._entry_ticket is not None:
            return
        if self._no_entry_date == current_date:
            return
        if self._has_option_position():
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        completed_close = self._add_minute_bar(bar)
        if completed_close is None:
            return

        bar_end = completed_close[0]
        close = completed_close[1]
        local_end = bar_end

        if not (local_end.hour == 9 and local_end.minute >= 45 or
                10 <= local_end.hour <= 13 or
                local_end.hour == 14 and local_end.minute <= 30):
            return

        if len(self._closes) >= 20:
            self._previous_fast = sum(list(self._closes)[-6:-1]) / 5 \
                if len(self._closes) >= 6 else None
            self._previous_slow = sum(list(self._closes)[-21:-1]) / 20 \
                if len(self._closes) >= 21 else None

        self._closes.append(close)

        if len(self._closes) < 20:
            return

        values = list(self._closes)
        fast = sum(values[-5:]) / 5
        slow = sum(values[-20:]) / 20

        previous_fast = self._previous_fast
        previous_slow = self._previous_slow

        self._previous_fast = fast
        self._previous_slow = slow

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = previous_fast <= previous_slow and fast > slow
        if bullish_cross:
            self._try_enter(slice, close, current_date)

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        if end_time.hour < 9 or end_time.hour > 16:
            return None
        if end_time.hour == 9 and end_time.minute <= 30:
            return None
        if end_time.hour == 16 and end_time.minute > 0:
            return None

        minute = end_time.hour * 60 + end_time.minute
        first_end = 9 * 60 + 35
        group_end = first_end + ((minute - first_end + 4) // 5) * 5

        if group_end < first_end:
            return None

        key = (end_time.date(), group_end)
        self._five_minute_bars[key][minute] = bar

        if minute != group_end:
            return None

        expected = set(range(group_end - 4, group_end + 1))
        group = self._five_minute_bars.pop(key, {})

        if set(group.keys()) != expected:
            return None

        ordered = [group[m] for m in sorted(group)]
        close = ordered[-1].Close
        return end_time, close

    def _try_enter(self, slice, spy_price, current_date):
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if contract.Right == OptionRight.Call and expiry_date >= minimum_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no eligible call expiration")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        strike_floor = 1.01 * spy_price

        strikes = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= strike_floor
        ]

        if not strikes:
            self.Debug("Skipped entry: no eligible strike")
            return

        selected = min(
            strikes,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_symbol = selected.Symbol
        self._entry_price = None
        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
