from collections import defaultdict
from datetime import datetime, timedelta, time

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Securities import DataNormalizationMode
from QuantConnect.Orders import OrderStatus
from QuantConnect import OptionRight


class SpyBullishCrossoverOptions(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_end = None
        self.bucket_bars = {}
        self.last_spy_price = None

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_date = None

    def OnData(self, slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position(today)

        if self.held_symbol is not None:
            self._process_position_protection(today, slice)

        spy_bar = slice.Bars.get(self.spy)
        bullish_signal = False
        signal_end = None

        if spy_bar is not None:
            self.last_spy_price = spy_bar.Close
            signal_end, bullish_signal = self._process_spy_minute(spy_bar)

        if (
            bullish_signal
            and signal_end is not None
            and time(9, 45) <= signal_end.time() <= time(14, 30)
            and self.blocked_date != today
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._enter_from_current_chain(slice, today)

    def _process_spy_minute(self, bar):
        end_time = bar.EndTime
        local_end = end_time

        if not (time(9, 30) < local_end.time() <= time(16, 0)):
            return None, False

        minute = local_end.hour * 60 + local_end.minute
        bucket_end_minutes = ((minute - 570) // 5 + 1) * 5
        bucket_end = datetime(
            local_end.year,
            local_end.month,
            local_end.day
        ) + timedelta(minutes=bucket_end_minutes)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            signal_end, signal = self._finalize_bucket()
            self.bucket_bars = {}

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end

        self.bucket_bars[local_end] = bar
        return self._finalize_if_complete(), False

    def _finalize_if_complete(self):
        if self.bucket_end is None or len(self.bucket_bars) != 5:
            return None

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if sorted(self.bucket_bars.keys()) != expected:
            return None

        closes = [self.bucket_bars[t].Close for t in expected]
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(self.bucket_end, closes[-1])
        self.slow.Update(self.bucket_end, closes[-1])

        bullish = (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        return self.bucket_end, bullish

    def _finalize_bucket(self):
        result = self._finalize_if_complete()
        if result is None:
            return None, False
        return result

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        terminal = {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        }
        return self.entry_ticket.Status not in terminal

    def _enter_from_current_chain(self, slice, today):
        if slice.OptionChains is None or slice.OptionChains.Count == 0:
            self.Debug("Skipped entry: no option chain.")
            return

        if self.last_spy_price is None or self.last_spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < today + timedelta(days=7):
                    continue

                if contract.Strike < 1.01 * self.last_spy_price:
                    continue

                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying option contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                nearest_expiry,
                selected.Strike
            )
        )

    def _process_position_protection(self, today, slice):
        if self.held_symbol is None:
            return

        security_holding = self.Portfolio[self.held_symbol]
        if security_holding.Quantity <= 0:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if today >= expiry:
            self.blocked_date = today
            self._submit_exit("Expiration protection")
            return

        prior_trading_day = self._prior_trading_day(expiry)
        if (
            today == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.exit_ticket is not None and self._exit_order_open():
            return

        contract = slice.OptionChains
        bid = None
        ask = None

        if contract is not None and contract.Count > 0:
            for chain in contract.Values:
                candidate = chain.Contracts.get(self.held_symbol)
                if candidate is not None:
                    bid = candidate.BidPrice
                    ask = candidate.AskPrice
                    break

        if (
            bid is None
            or ask is None
            or bid <= 0
            or ask <= 0
            or self.entry_price is None
        ):
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        }

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_orders()

        if self._exit_order_open():
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {0}".format(reason))

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and self._exit_order_open():
            self.exit_ticket.Cancel("Canceled before replacement exit")
            self.exit_ticket = None

    def _prior_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_equity_position(self, today):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.blocked_date = today
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

    def OnAssignmentOrderEvent(self, assignmentEvent):
        self.blocked_date = self.Time.date()
        self.Debug("Unexpected assignment event: liquidating SPY.")
        self.Liquidate(self.spy, "Unexpected assignment")

    def OnOrderEvent(self, orderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status in {
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            }:
                if self.held_symbol is None:
                    self.held_symbol = orderEvent.Symbol
                    self.entry_price = orderEvent.FillPrice
                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )

                if orderEvent.Status == OrderStatus.Filled:
                    self.entry_ticket = None

            elif orderEvent.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        orderEvent.Symbol,
                        orderEvent.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif orderEvent.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.exit_ticket = None

        if getattr(orderEvent, "IsAssignment", False):
            self.blocked_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment event handled.")
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

