        self.fast.Update(self.bucket_end, closes[-1])
        self.slow.Update(self.bucket_end, closes[-1])

        bullish = (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        return self.bucket_end, bullish

    def _finalize_bucket(self):
        result = self._finalize_if_complete()
        if result is None:
            return None, False
        return result

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        terminal = {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        }
        return self.entry_ticket.Status not in terminal

    def _enter_from_current_chain(self, slice, today):
        if slice.OptionChains is None or slice.OptionChains.Count == 0:
            self.Debug("Skipped entry: no option chain.")
            return

        if self.last_spy_price is None or self.last_spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < today + timedelta(days=7):
                    continue

                if contract.Strike < 1.01 * self.last_spy_price:
                    continue

                contracts.append(contract)

