        if self.held_symbol is None:
            return

        security_holding = self.Portfolio[self.held_symbol]
        if security_holding.Quantity <= 0:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if today >= expiry:
            self.blocked_date = today
            self._submit_exit("Expiration protection")
            return

        prior_trading_day = self._prior_trading_day(expiry)
        if (
            today == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.exit_ticket is not None and self._exit_order_open():
            return

        contract = slice.OptionChains
        bid = None
        ask = None

        if contract is not None and contract.Count > 0:
            for chain in contract.Values:
                candidate = chain.Contracts.get(self.held_symbol)
                if candidate is not None:
                    bid = candidate.BidPrice
                    ask = candidate.AskPrice
                    break

        if (
            bid is None
            or ask is None
            or bid <= 0
            or ask <= 0
            or self.entry_price is None
        ):
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        }

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_orders()

        if self._exit_order_open():
