        self.held_symbol = None
        self.entry_price = None
        self.exit_submitted = False
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime

        if end_time.hour < 9 or end_time.hour > 16:
            return

        if end_time.hour == 9 and end_time.minute < 35:
            return

        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(
            self.closes[i] for i in range(5)
        ) / 5.0
        current_slow = sum(
            self.closes[i] for i in range(20)
        ) / 20.0

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
            and (
                (end_time.hour > 9)
                or (end_time.hour == 9 and end_time.minute >= 45)
            )
            and (
                (end_time.hour < 14)
                or (end_time.hour == 14 and end_time.minute <= 30)
            )
        ):
            self.pending_signal_time = end_time

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.Portfolio[self.spy_symbol].Invested:
            self.blocked_entry_date = current_date
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity,
                tag="Unexpected exercise or assignment"
            )

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self.Debug(
                    "Expiration processing began; liquidating held option."
                )
                self.SubmitExit("Expiration liquidation")
            else:
                stop_date = self.PrecedingTradingDay(expiry_date)
                if (
                    current_date == stop_date
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self.Debug("Time stop triggered; liquidating held option.")
                    self.SubmitExit("Expiration time stop")
                else:
                    self.CheckProfitTarget(slice)

        if self.pending_signal_time is not None:
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if self.Time == signal_time:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                return
            self.entry_ticket = None

        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        selected_expiry = expirations[0]
        spy_price = self.Securities[self.spy_symbol].Price

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        candidates.sort(
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Submitted SPY option entry: " + str(selected.Symbol))

    def CheckProfitTarget(self, slice):
        if self.held_symbol is None or self.exit_submitted:
            return

        if self.held_symbol not in slice.OptionChains:
            return

        chain = slice.OptionChains[self.held_symbol]
        contract = None

        for candidate in chain:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.Debug("Profit target reached; liquidating option.")
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, tag):
        if self.held_symbol is None or self.exit_submitted:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            self.ClearPositionState()
            return

        for order in self.Transactions.GetOpenOrders():
            if order.Symbol == self.held_symbol:
                self.Transactions.CancelOrder(order.Id)

        self.exit_submitted = True
        self.MarketOrder(self.held_symbol, -quantity, tag=tag)

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.exit_submitted = False
                self.entry_ticket = None
                self.Debug(
                    "SPY option entry filled at "
                    + str(self.entry_price)
                    + ": "
                    + str(self.held_symbol)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("SPY option entry order did not fill.")
                self.entry_ticket = None

        if (
            self.held_symbol is not None
            and order_event.Symbol == self.held_symbol
            and order_event.Status == OrderStatus.Filled
            and self.Portfolio[self.held_symbol].Quantity == 0
        ):
            self.Debug("SPY option position exited.")
            self.ClearPositionState()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.blocked_entry_date = self.Time.date()
        self.Debug("Unexpected option exercise or assignment; liquidating SPY.")

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity,
                tag="Unexpected exercise or assignment"
            )

    def PrecedingTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def ClearPositionState(self):
        self.held_symbol = None
        self.entry_price = None
        self.exit_submitted = False

