        self.previous_slow = self.slow.Current.Value

        bar_end = completed_bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter(slice, current_date, completed_bar.Close)

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return None

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self._bucket_end is None:
            self._bucket_end = bucket_end

        if bucket_end != self._bucket_end:
