        ]

        if any(t not in self._bucket_bars for t in expected_times):
            return None

        bars = [self._bucket_bars[t] for t in sorted(expected_times)]

        return TradeBar(
            self._bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

    def _try_enter(self, slice, current_date, spy_price):
        if current_date == self.blocked_entry_date:
            return

        if self.Portfolio[self.spy].Quantity != 0:
            return

        if self.entry_symbol is not None and (
            self.Portfolio[self.entry_symbol].Invested
            or self._is_order_open(self.entry_ticket)
        ):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        if not slice.OptionChains.ContainsKey(self.option_canonical):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_canonical]
        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration or call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        strike_floor = 1.01 * spy_price

        candidates = [
