            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiration {} strike {:.2f}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_option_exit(self, slice, current_date, expiry):
        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        previous_trading_day = self._previous_trading_day(expiry)
        time_stop = (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        )

        quote = slice.QuoteBars.get(self.entry_symbol)
        midpoint = None

        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            if bid is not None and ask is not None and bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0

        profit_target = (
            midpoint is not None
            and self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        )

        if profit_target:
            self._liquidate_option_position("50% profit target")
        elif time_stop:
