from AlgorithmImports import *
from collections import deque
from datetime import timedelta, datetime


class SpyOptionMovingAverageStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.held_option = None
        self.held_expiry = None
        self.expiration_processing_date = None
        self.equity_cleanup_ticket = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self._input_times = []

    def OnData(self, slice):
        self.current_slice = slice

        self._liquidate_unexpected_equity()

        if self.spy in slice.Bars:
            minute_bar = slice.Bars[self.spy]
            self._input_times.append(minute_bar.EndTime)
            self.consolidator.Update(minute_bar)

        if self.held_option is not None:
            self._evaluate_exit(slice)

    def OnFiveMinuteBar(self, sender, bar):
        valid_bar = (
            len(self._input_times) == 5 and
            all(
                self._input_times[i] - self._input_times[i - 1]
                == timedelta(minutes=1)
                for i in range(1, len(self._input_times))
            )
        )
        self._input_times = []

        if not valid_bar:
            return

        local_end = bar.EndTime
        if local_end.hour < 9 or local_end.hour > 16:
            return

        if (
            local_end.hour == 9 and local_end.minute < 35
        ) or (
            local_end.hour == 16 and local_end.minute > 0
        ):
            return

        self.fast_values.append(float(bar.Close))
        self.slow_values.append(float(bar.Close))

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(list(self.fast_values)[-5:]) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (
            (local_end.hour == 9 and local_end.minute >= 45) or
            (10 <= local_end.hour <= 13) or
            (local_end.hour == 14 and local_end.minute <= 30)
        ):
            return

        if self.expiration_processing_date == self.Time.date():
            return

        if self._has_open_entry() or self._has_option_holding():
            return

        self._enter_option(float(bar.Close))

    def _enter_option(self, spy_price):
        if self.current_slice is None:
            self.Debug("Skipped entry: no current Slice.")
            return

        chains = list(self.current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying option contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish MA crossover entry"
        )
        self.held_option = selected.Symbol
        self.held_expiry = nearest_expiry
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={nearest_expiry}"
        )

    def _evaluate_exit(self, slice):
        if self.held_option is None or self.held_expiry is None:
            return

        today = self.Time.date()

        if today >= self.held_expiry:
            self.expiration_processing_date = today
            self._submit_option_exit("Expiration protection")
            return

        prior_trading_day = self._prior_trading_day(self.held_expiry)
        if today == prior_trading_day and self.Time.hour >= 15 and self.Time.minute >= 45:
            self._submit_option_exit("Pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        bid = None
        ask = None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    bid = float(contract.BidPrice)
                    ask = float(contract.AskPrice)
                    break
            if bid is not None:
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason} for {self.held_option}")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {order_event.Symbol} "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.held_option = None
                self.held_expiry = None
                self.Debug("Entry order did not fill.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.entry_price = None
                self.held_option = None
                self.held_expiry = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
