from collections import deque
from datetime import timedelta, time


class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.spy_option.Symbol
        self.spy_option.SetFilter(
            lambda universe: universe
                .Strikes(-1000, 1000)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self._bucket_start = None
        self._bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(today)

        current_chain = None
        if self.option_symbol in slice.OptionChains:
            current_chain = slice.OptionChains[self.option_symbol]

        completed_bar = None
        if self.spy_symbol in slice.Bars:
            completed_bar = self._process_minute_bar(slice.Bars[self.spy_symbol])

        self._evaluate_open_position(slice, today)

        if completed_bar is None:
            return

        bar_end, close = completed_bar
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.held_option is not None or self._entry_order_open():
            return

        if self.expiration_block_date == today:
            return

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        previous_fast = sum(list(self.fast_closes)[-5:]) / 5.0
        previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_cross:
            self._try_enter(current_chain, close, today)

    def _process_minute_bar(self, bar):
        timestamp = bar.EndTime
        if timestamp.tzinfo is not None:
            timestamp = timestamp.replace(tzinfo=None)

        if timestamp.time() < time(9, 30) or timestamp.time() >= time(16, 0):
            return None

        minute = timestamp.replace(second=0, microsecond=0)
        bucket_start = minute - timedelta(minutes=minute.minute % 5)

        completed = None
        if self._bucket_start is not None and bucket_start != self._bucket_start:
            completed = self._complete_bucket()

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_bars = []

        self._bucket_bars.append(bar)
        return completed

    def _complete_bucket(self):
        bars = self._bucket_bars
        bucket_start = self._bucket_start
        self._bucket_bars = []

        if len(bars) != 5:
            return None

        expected = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]
        actual = []
        for bar in bars:
            stamp = bar.EndTime
            if stamp.tzinfo is not None:
                stamp = stamp.replace(tzinfo=None)
            actual.append(stamp.replace(second=0, microsecond=0))

        if actual != expected:
            return None

        close = float(bars[-1].Close)
        bar_end = bucket_start + timedelta(minutes=5)

        if not (time(9, 30) <= bucket_start.time() < time(16, 0)):
            return None

        if len(self.fast_closes) >= 5 and len(self.slow_closes) >= 20:
            previous_fast = sum(list(self.fast_closes)[-5:]) / 5.0
            previous_slow = sum(self.slow_closes) / 20.0
        else:
            previous_fast = previous_slow = None

        self._last_previous_fast = previous_fast
        self._last_previous_slow = previous_slow

        return bar_end, close

    def _try_enter(self, chain, spy_price, today):
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible_expiries = sorted({
            c.Expiry.date()
            for c in chain
            if c.Expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            c for c in chain
            if c.Expiry.date() == selected_expiry
            and c.Right == OptionRight.Call
            and float(c.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        contract = candidates[0]

        self.entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="Bullish five-minute MA crossover"
        )
        self.Debug(
            "Entry submitted: {} expiry {} strike {:.2f}".format(
                contract.Symbol, selected_expiry, float(contract.Strike)
            )
        )

    def _evaluate_open_position(self, slice, today):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        current_time = self.Time.time()

        if (
            current_time >= time(15, 45)
            and self._next_trading_day(today) == expiry_date
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        if self.entry_price is None or self.held_option not in slice.OptionChains:
            return

        chain = slice.OptionChains[self.held_option]
        contract = next(
            (c for c in chain if c.Symbol == self.held_option),
            None
        )

        if contract is None:
            return

        try:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)
        except (TypeError, ValueError):
            return

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self._exit_order_open():
            self.exit_ticket.Cancel("Replaced by higher-priority exit: " + reason)

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}".format(reason))

    def _handle_expiration_processing(self, today):
        if self.held_option is None:
            if self.expiration_block_date == today:
                return
            return

        expiry_date = self.held_option.ID.Date.date()
        if today >= expiry_date:
            self.expiration_block_date = today
            self._submit_exit("Expiration processing liquidation")

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            self.equity_liquidation_submitted = False
            return

        if not self.equity_liquidation_submitted:
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment handling"
            )
            self.equity_liquidation_submitted = True

    def _next_trading_day(self, date):
        candidate = date + timedelta(days=1)
        hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate += timedelta(days=1)

        return candidate

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None and
                order_event.OrderId == self.entry_ticket.OrderId
            ):
                if order_event.FillQuantity > 0:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self.held_option, self.entry_price
                        )
                    )

            elif (
                self.exit_ticket is not None and
                order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                if (
                    self.held_option == order_event.Symbol and
                    self.Portfolio[order_event.Symbol].Quantity == 0
                ):
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None

        elif self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order did not fill: {}".format(order_event.Status))
                self.entry_ticket = None

