            -100,
            100,
            timedelta(days=0),
            timedelta(days=730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.expiration_stop_date = None
        self.block_entry_date = None
        self.assignment_liquidation_ticket = None

    def OnData(self, slice):
        algorithm_date = self.Time.date()

        self._handle_unexpected_spy_position(algorithm_date)
        self._handle_expiration_processing(algorithm_date)
        self._evaluate_held_position(slice, algorithm_date)

        if self.spy_symbol not in slice.Bars:
            return

        completed_bar = self._update_five_minute_bar(slice.Bars[self.spy_symbol])
        if completed_bar is None:
            return

        bar_end = completed_bar["end"]
        self._update_averages(completed_bar["close"])

        if self.block_entry_date == algorithm_date:
            return

        if (
            bar_end.hour < 9
            or (bar_end.hour == 9 and bar_end.minute < 45)
            or bar_end.hour > 14
            or (bar_end.hour == 14 and bar_end.minute > 30)
        ):
            return

        if not self._bullish_crossover():
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        self._enter_from_current_chain(slice, algorithm_date)

    def _update_five_minute_bar(self, minute_bar):
        local_time = minute_bar.Time.astimezone(self.TimeZone)
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.weekday() >= 5:
            return None

        session_start = local_time.replace(hour=9, minute=30, second=0, microsecond=0)
        session_end = local_time.replace(hour=16, minute=0, second=0, microsecond=0)

        if local_time < session_start or local_time >= session_end:
            return None

        minutes_from_open = int((local_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if (
            self.current_bucket_start is not None
            and bucket_start != self.current_bucket_start
        ):
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = []

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = []

        if bucket_start != self.current_bucket_start:
            return None

        self.current_bucket_bars.append(minute_bar)

        if len(self.current_bucket_bars) < 5:
            return None

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]
        actual_times = [bar.Time.astimezone(self.TimeZone).replace(tzinfo=None)
                        for bar in self.current_bucket_bars]

        completed = None
        if actual_times == expected_times:
            completed = {
                "end": self.current_bucket_start + timedelta(minutes=5),
                "open": self.current_bucket_bars[0].Open,
                "high": max(bar.High for bar in self.current_bucket_bars),
                "low": min(bar.Low for bar in self.current_bucket_bars),
                "close": self.current_bucket_bars[-1].Close,
                "volume": sum(bar.Volume for bar in self.current_bucket_bars)
            }

        self.current_bucket_start = None
        self.current_bucket_bars = []
        return completed

    def _update_averages(self, close):
        self.fast_values.append(float(close))
        self.slow_values.append(float(close))

        current_fast = None
        current_slow = None

        if len(self.fast_values) == 5:
            current_fast = sum(self.fast_values) / 5.0
        if len(self.slow_values) == 20:
            current_slow = sum(self.slow_values) / 20.0

        self.previous_fast = getattr(self, "current_fast", None)
        self.previous_slow = getattr(self, "current_slow", None)
        self.current_fast = current_fast
        self.current_slow = current_slow

    def _bullish_crossover(self):
        return (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.current_fast is not None
            and self.current_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.current_fast > self.current_slow
        )

    def _enter_from_current_chain(self, slice, algorithm_date):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiration = eligible_expirations[0]
        minimum_strike = float(self.Securities[self.spy_symbol].Price) * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_held_position(self, slice, algorithm_date):
        if self.held_symbol is None:
            return

        if self.block_entry_date == algorithm_date:
            return

        if (
            self.expiration_stop_date is not None
            and algorithm_date == self.expiration_stop_date
            and self.Time.hour > 15
            or (
                self.expiration_stop_date is not None
                and algorithm_date == self.expiration_stop_date
                and self.Time.hour == 15
                and self.Time.minute >= 45
            )
        ):
            self._submit_exit("time stop")
            return

        contract = self._find_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid > 0 and ask > 0 and self.entry_price is not None:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self._submit_exit("50% profit target")

    def _handle_expiration_processing(self, algorithm_date):
        if self.held_symbol is None:
            return

        if self.expiration_stop_date is not None and algorithm_date >= self._held_expiration:
            self.block_entry_date = algorithm_date
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def _find_contract(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _handle_unexpected_spy_position(self, algorithm_date):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity != 0:
            self.block_entry_date = algorithm_date
            if self.assignment_liquidation_ticket is None:
                self.assignment_liquidation_ticket = self.MarketOrder(
                    self.spy_symbol,
                    -quantity
                )
                self.Debug("Unexpected SPY exercise/assignment handled.")

        elif self.assignment_liquidation_ticket is not None:
            self.assignment_liquidation_ticket = None

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_symbol
                self.entry_price = float(order_event.FillPrice)
                self._held_expiration = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date.date()

                self.expiration_stop_date = self._previous_trading_day(
                    self._held_expiration
                )
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self.held_symbol))
            self.held_symbol = None
            self.entry_symbol = None
            self.entry_price = None
            self.expiration_stop_date = None
            self._held_expiration = None
            self.exit_ticket = None

        if "Exercise" in str(order_event.OrderType) or "Assignment" in str(order_event.OrderType):
            self.block_entry_date = self.Time.date()
            self._handle_unexpected_spy_position(self.Time.date())

    def OnAssignmentOrderEvent(self, assignment_event):
        self.block_entry_date = self.Time.date()
        self.Debug("Unexpected option assignment handled.")
        self._handle_unexpected_spy_position(self.Time.date())

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while candidate >= self.StartDate.date():
            if self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate):
                return candidate
            candidate -= timedelta(days=1)

        return expiration_date - timedelta(days=1)

