        self.close_history = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._process_held_option(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, data)

    def _process_minute_bar(self, bar, data):
        current = self.Time.replace(second=0, microsecond=0)
        local_time = current.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute = current.hour * 60 + current.minute
        session_start = 9 * 60 + 30
        elapsed_end = minute - session_start

        if elapsed_end <= 0:
            return

        bucket_index = (elapsed_end - 1) // 5
        bucket_start_minute = session_start + bucket_index * 5
        bucket_end_minute = bucket_start_minute + 5

        bucket_key = current.date(), bucket_start_minute
        bucket = self.minute_bars.setdefault(bucket_key, {})
        bucket[minute] = bar.Close

        if minute != bucket_end_minute:
            return

        expected_minutes = set(range(bucket_start_minute + 1, bucket_end_minute + 1))
        closes = [bucket.get(m) for m in expected_minutes]
        del self.minute_bars[bucket_key]

        if any(close is None for close in closes):
            return

        five_minute_close = closes[-1]
        self.close_history.append(five_minute_close)

        if len(self.close_history) < 20:
            return

        current_fast = sum(list(self.close_history)[-5:]) / 5.0
        current_slow = sum(self.close_history) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        bar_end_time = current.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if bullish_cross and eligible_time:
            self._evaluate_entry(data, five_minute_close)

