        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        strike_floor = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry and
            contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _process_held_option(self, data):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self.expiration_block_date = today
            self._submit_exit("Expiration liquidation")
            return

        prior_trading_day = self._previous_trading_day(expiry)
        if (
            today == prior_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.entry_price is None or self._exit_order_is_open():
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_is_open():
            if self.exit_ticket is not None:
                self.exit_ticket.Cancel("Replaced by liquidation order")
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(self.held_symbol, reason)
        )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ):
                if self.held_symbol is None:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {} at {}".format(
                            self.held_symbol, self.entry_price
                        )
                    )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ):
                if not self.Portfolio[self.held_symbol].Invested:
                    self.Debug(
                        "Exit filled: {} at {}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ) and not self.Portfolio[order_event.Symbol].Invested:
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected exercise or assignment: {}".format(
                    order_event.Symbol
                )
            )
            self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None and
            self.equity_liquidation_ticket.Status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.New
            )
        ):
            return

        self.Debug(
            "Unexpected SPY exercise or assignment position: {} shares."
            .format(quantity)
        )
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Liquidate unexpected exercise or assignment"
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

