from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.SetSecurityInitializer(
            lambda security: security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        )

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe.Strikes(-500, 500).Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.current_bucket_end = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.blocked_entry_date = None
        self.assignment_liquidation_pending = False

    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        self._liquidate_unexpected_spy_position()

        held_symbol = self._held_option_symbol()

        if held_symbol is not None:
            expiry_date = self.Securities[held_symbol].Symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self.Debug(
                    "Expiration processing: liquidating {}".format(held_symbol)
                )
                self._submit_exit("expiration")
            else:
                stop_date = self._previous_trading_day(expiry_date)

                if current_date == stop_date and now.hour == 15 and now.minute >= 45:
                    self.Debug(
                        "Time stop: liquidating {} before expiration".format(
                            held_symbol
                        )
                    )
                    self._submit_exit("time stop")
                else:
                    self._evaluate_profit_target(slice, held_symbol)

        if self.spy_symbol in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy_symbol], now, slice)

    def _update_five_minute_bar(self, minute_bar, local_end, slice):
        local_end = local_end.replace(second=0, microsecond=0)
        if local_end.time() < self._time(9, 31) or local_end.time() > self._time(16, 0):
            return

        minute = local_end.minute
        bucket_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = local_end.replace(minute=0) + timedelta(minutes=bucket_minute)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
        elif bucket_end != self.current_bucket_end:
            self._finalize_bucket(self.current_bucket_end)
            self.current_bucket_bars = {}
            self.current_bucket_end = bucket_end

        self.current_bucket_bars[local_end] = minute_bar

        if local_end == bucket_end:
            self._finalize_bucket(bucket_end)
            self.current_bucket_bars = {}
            self.current_bucket_end = None

            self._evaluate_entry_signal(slice, bucket_end)

    def _finalize_bucket(self, bucket_end):
        if self.current_bucket_end != bucket_end:
            return

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(timestamp not in self.current_bucket_bars for timestamp in expected):
            return

        bars = [self.current_bucket_bars[timestamp] for timestamp in expected]
        close = bars[-1].Close

        previous_fast = None
        previous_slow = None
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(float(close))

        if previous_fast is not None:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
            current_slow = sum(self.closes) / 20.0

            if (
                previous_fast <= previous_slow
                and current_fast > current_slow
            ):
                self.pending_signal = bucket_end

