from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(0, 180)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.close_window = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition(today)

        if self.held_symbol is not None:
            self.HandleExpirationProcessing(today)
            self.EvaluateHeldPosition(slice, today)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy.Symbol):
            spy_bar = slice.Bars[self.spy.Symbol]

        if spy_bar is not None:
            self.ProcessMinuteBar(spy_bar, slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        local_start = bar.Time
        local_end = bar.EndTime
        session_start = datetime(local_start.year, local_start.month, local_start.day, 9, 30)
        session_end = datetime(local_start.year, local_start.month, local_start.day, 16, 0)

        if local_start < session_start or local_end > session_end:
            return

        elapsed_minutes = int((local_start - session_start).total_seconds() / 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self.EmitCompletedBar(slice)
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        if local_start not in self.bucket_bars:
            self.bucket_bars[local_start] = bar

        if len(self.bucket_bars) == 5:
            self.EmitCompletedBar(slice)
            self.bucket_start = None
            self.bucket_bars = {}

    def EmitCompletedBar(self, slice: Slice):
        if self.bucket_start is None or len(self.bucket_bars) != 5:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if any(timestamp not in self.bucket_bars for timestamp in expected_times):
            return

        bars = [self.bucket_bars[timestamp] for timestamp in expected_times]
        close = bars[-1].Close
        completed_end = self.bucket_start + timedelta(minutes=5)

        self.close_window.append(float(close))
        if len(self.close_window) > self.slow_period:
            self.close_window.pop(0)

        if len(self.close_window) < self.slow_period:
            return

        fast = sum(self.close_window[-self.fast_period:]) / self.fast_period
        slow = sum(self.close_window[-self.slow_period:]) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= completed_end.time() <= time(14, 30)):
            return

        self.TryEnter(slice, close, completed_end)

    def TryEnter(self, slice: Slice, spy_price: float, bar_end: datetime):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        chain = self.GetCurrentOptionChain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible = []
        minimum_expiry = today + timedelta(days=7)

        for contract in self.IterateContracts(chain):
            expiry_date = contract.Expiry.date()
            if (
                contract.Right == OptionRight.Call
                and expiry_date >= minimum_expiry
                and contract.Strike >= 1.01 * spy_price
            ):
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no eligible option contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        eligible = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def EvaluateHeldPosition(self, slice: Slice, today):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        held_security = self.Securities[self.held_symbol]
        expiry_date = held_security.Symbol.ID.Date.date()

        if self.IsTradingDayImmediatelyBefore(expiry_date, today):
            if self.Time.time() >= time(15, 45):
                self.SubmitExit("time stop")
                return

        contract = self.GetHeldContract(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def HandleExpirationProcessing(self, today):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if today >= expiry_date:
            self.no_entry_date = today
            self.SubmitExit("expiration protection")

    def SubmitExit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted (" + reason + "): " + str(self.held_symbol))

    def HandleUnexpectedEquityPosition(self, today):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        self.no_entry_date = today

        if quantity != 0:
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.MarketOrder(self.spy.Symbol, -quantity)

    def GetCurrentOptionChain(self, slice: Slice):
        for chain in slice.OptionChains.Values:
            if chain.Symbol == self.spy_option.Symbol:
                return chain
        return None

    def GetHeldContract(self, slice: Slice):
        for chain in slice.OptionChains.Values:
            for contract in self.IterateContracts(chain):
                if contract.Symbol == self.held_symbol:
                    return contract
        return None

    def IterateContracts(self, chain):
        for contract in chain:
            yield contract

    def IsTradingDayImmediatelyBefore(self, expiry_date, current_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate >= current_date - timedelta(days=10):
            if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(candidate):
                return current_date == candidate
            candidate -= timedelta(days=1)

        return False

    def IsOpen(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_price)
                )
            elif not self.IsOpen(self.entry_ticket):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif not self.IsOpen(self.exit_ticket):
                self.exit_ticket = None

        if order_event.Symbol == self.spy.Symbol:
            if self.Portfolio[self.spy.Symbol].Quantity != 0:
                self.no_entry_date = self.Time.date()
                self.Debug("Unexpected SPY position after option processing.")
                self.MarketOrder(
                    self.spy.Symbol,
                    -self.Portfolio[self.spy.Symbol].Quantity
                )


