from AlgorithmImports import *
from datetime import datetime, timedelta, time
import pytz


class SpyBullishCrossoverOptions(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=365))
        )

        self._ny_tz = pytz.timezone("America/New_York")
        self._bucket_date = None
        self._bucket_end = None
        self._bucket_bars = {}

        self._closes = []
        self._previous_fast = None
        self._previous_slow = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_held_position(slice)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy.Symbol):
            spy_bar = slice.Bars[self.spy.Symbol]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = self._to_new_york(bar.Time)

        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            9,
            30
        )
        minutes_from_open = int((local_time - bucket_start).total_seconds() // 60)
        bucket_number = minutes_from_open // 5
        bucket_end = bucket_start + timedelta(minutes=(bucket_number + 1) * 5)

        if self._bucket_end is not None and bucket_end != self._bucket_end:
            self._bucket_bars = {}

        self._bucket_end = bucket_end
        self._bucket_date = local_time.date()
        self._bucket_bars[local_time] = bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if not all(t in self._bucket_bars for t in expected_times):
            return

        bars = [self._bucket_bars[t] for t in sorted(expected_times)]
        close = bars[-1].Close

        self._bucket_bars = {}
        self._update_moving_averages(close, bucket_end, slice)

    def _update_moving_averages(self, close: float, bar_end: datetime, slice: Slice):
        self._closes.append(float(close))
        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        fast = sum(self._closes[-5:]) / 5.0
        slow = sum(self._closes[-20:]) / 20.0

        bullish_cross = (
            self._previous_fast is not None and
            self._previous_slow is not None and
            self._previous_fast <= self._previous_slow and
            fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter(slice, float(close), bar_end.date())

    def _try_enter(self, slice: Slice, spy_price: float, algorithm_date):
        if self._blocked_entry_date == algorithm_date:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._ticket_is_open(self._entry_ticket):
            return

        if slice.OptionChains is None or len(slice.OptionChains) == 0:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        nearest_expiry = min(c.Expiry.date() for c in contracts)
        eligible = [
            c for c in contracts
            if c.Expiry.date() == nearest_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no contract at selected expiration")
            return

        selected = min(
            eligible,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiration {selected.Expiry.date()}, strike {selected.Strike}"
        )

    def _process_held_position(self, slice: Slice):
        if self._held_symbol is None:
            return

        held = self._held_symbol
        expiry_date = self.Securities[held].Symbol.ID.Date.date()

        current_date = self.Time.date()

        if current_date >= expiry_date:
            self._blocked_entry_date = current_date
            if self._has_option_quantity(held) and not self._has_open_exit():
                self._submit_exit("expiration")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            if self._has_option_quantity(held) and not self._has_open_exit():
                self._submit_exit("pre-expiration time stop")
            return

        if not self._has_option_quantity(held):
            return

        contract = None
        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(held):
                contract = chain.Contracts[held]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self._entry_price is not None and
            midpoint >= 1.50 * self._entry_price and
            not self._has_open_exit()
        ):
            self._submit_exit("profit target")

    def _submit_exit(self, reason: str):
        if self._held_symbol is None:
            return

        if self._exit_ticket is not None and self._ticket_is_open(self._exit_ticket):
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        if reason == "profit target":
            self._cancel_open_exit_orders()

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity
        )
        self.Debug(f"Exit submitted ({reason}): {self._held_symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        symbol = order_event.Symbol

        if (
            self._entry_ticket is not None and
            order_event.OrderId == self._entry_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self._held_symbol = symbol
            self._entry_price = float(order_event.FillPrice)
            self._entry_ticket = None
            self.Debug(
                f"Entry filled: {symbol}, price {self._entry_price:.4f}"
            )

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {symbol}, price {order_event.FillPrice:.4f}")
            if not self._has_option_quantity(symbol):
                self._held_symbol = None
                self._entry_price = None
                self._exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(f"Unexpected exercise or assignment: {symbol}")
            self._blocked_entry_date = self.Time.date()
            self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected; liquidating {quantity}"
            )
            self.MarketOrder(self.spy.Symbol, -quantity)
            self._blocked_entry_date = self.Time.date()

    def _cancel_open_exit_orders(self):
        if self._exit_ticket is not None and self._ticket_is_open(self._exit_ticket):
            self._exit_ticket.Cancel("Profit target reached")

    def _has_open_exit(self):
        return (
            self._exit_ticket is not None and
            self._ticket_is_open(self._exit_ticket)
        )

    def _has_option_quantity(self, symbol):
        return self.Portfolio[symbol].Quantity != 0

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        dt = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        )
        previous = self.Securities[self.spy.Symbol].Exchange.Hours.GetPreviousTradingDay(dt)
        return previous.date()

    def _to_new_york(self, value):
        if value.tzinfo is None:
            return self._ny_tz.localize(value)
        return value.astimezone(self._ny_tz)

