from collections import deque
from datetime import timedelta


class SpyBullishOptionCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe.Strikes(-1000, 1000).Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.contract_expiration = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.equity_liquidation_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_equity_position()
        self._handle_expiration_processing()
        self._evaluate_open_position_exit(slice)

        if self._entry_order_open() or self._option_position_exists():
            self._consume_spy_bar(slice)
            return

        if self.no_entry_date == current_date:
            self._consume_spy_bar(slice)
            return

        self._consume_spy_bar(slice, slice)

    def _consume_spy_bar(self, slice: Slice, signal_slice=None):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        end_time = bar.EndTime

        if end_time.date() != self.Time.date():
            return

        minutes = end_time.hour * 60 + end_time.minute
        if minutes < 9 * 60 + 31 or minutes > 16 * 60:
            return

        session_start = end_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        minutes_from_start = int((end_time - session_start).total_seconds() // 60)

        if minutes_from_start < 1:
            return

        bucket_number = (minutes_from_start - 1) // 5
        bucket_end = session_start + timedelta(minutes=(bucket_number + 1) * 5)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = []

        if self.current_bucket_bars:
            expected_end = self.current_bucket_bars[-1].EndTime + timedelta(minutes=1)
            if end_time != expected_end:
                self.current_bucket_bars = []

        self.current_bucket_bars.append(bar)

        if end_time != bucket_end:
            return

        bars = self.current_bucket_bars
        self.current_bucket_bars = []

        if len(bars) != 5:
            return

        for first, second in zip(bars, bars[1:]):
            if second.EndTime != first.EndTime + timedelta(minutes=1):
                return

        self._process_five_minute_close(bar.Close, bucket_end, signal_slice or slice)

    def _process_five_minute_close(self, close, bar_end, slice):
        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.closes.append(float(close))

        if len(self.closes) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_crossover = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_time = bar_end.time()
        eligible = (
            bar_time >= self._time(9, 45)
            and bar_time <= self._time(14, 30)
        )

        if bullish_crossover and eligible:
            self._try_enter(slice, float(close))

    def _try_enter(self, slice, spy_price):
        if self._entry_order_open() or self._option_position_exists():
            return

        chains = []
        for chain in slice.OptionChains:
            if chain.Symbol.Underlying == self.spy.Symbol:
                chains.append(chain)

        if not chains:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        if not contracts:
            self.Debug("Skipped entry: option chain contained no contracts.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        expiration_dates = sorted(
            {
                contract.Expiration.date()
                for contract in contracts
                if contract.Expiration.date() >= minimum_expiration
            }
        )

        if not expiration_dates:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiration = expiration_dates[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiration.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call contract met the expiration and strike rules."
            )
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY five-minute crossover entry",
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={selected.Expiration.date()} strike={selected.Strike}"
        )

    def _evaluate_open_position_exit(self, slice: Slice):
        if self.held_symbol is None or not self._option_position_exists():
            return

        if self._exit_order_open():
            return

        if self._is_time_stop_due():
            self._submit_exit("expiration-eve time stop")
            return

        quote = self._get_current_quote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None or not self._option_position_exists():
            return

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason,
        )
        self.Debug(f"Exit submitted: {reason} symbol={self.held_symbol}")

    def _handle_expiration_processing(self):
        if self.held_symbol is None or self.contract_expiration is None:
            return

        current_date = self.Time.date()
        expiration_date = self.contract_expiration.date()

        if current_date >= expiration_date:
            self.no_entry_date = current_date
            if self._option_position_exists() and not self._exit_order_open():
                self._submit_exit("expiration processing liquidation")

    def _is_time_stop_due(self):
        if self.contract_expiration is None:
            return False

        current_date = self.Time.date()
        expiration_date = self.contract_expiration.date()

        if current_date >= expiration_date:
            return False

        if self.Time.time() < self._time(15, 45):
            return False

        if not self._is_trading_day(current_date):
            return False

        day = current_date + timedelta(days=1)
        while day < expiration_date:
            if self._is_trading_day(day):
                return False
            day += timedelta(days=1)

        return True

    def _is_trading_day(self, date):
        return self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(date)

    def _get_current_quote(self, slice, symbol):
        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        if symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]
            if quote.Bid is not None and quote.Ask is not None:
                return float(quote.Bid.Close), float(quote.Ask.Close)

        return None

    def _handle_equity_position(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity == 0:
            return

        current_date = self.Time.date()
        self.no_entry_date = current_date

        if self.equity_liquidation_date != current_date:
            self.equity_liquidation_date = current_date
            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"liquidating {holding.Quantity} SPY shares."
            )
            self.MarketOrder(
                self.spy.Symbol,
                -holding.Quantity,
                tag="Unexpected option exercise or assignment liquidation",
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        assignment = getattr(order_event, "IsAssignment", False)
        exercise = getattr(order_event, "IsExercise", False)

        if assignment or exercise:
            self.no_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected exercise or assignment event: {order_event.Message}"
            )
            self._handle_equity_position()

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.contract_expiration = (
                        self.Securities[self.held_symbol].Symbol.ID.Date
                    )
                    self.entry_ticket = None
                    self.Debug(
                        f"Entry filled: {self.held_symbol} "
                        f"price={self.entry_price}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                    self.contract_expiration = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.exit_ticket = None

    def _option_position_exists(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity > 0
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected,
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected,
        )

    @staticmethod
    def _time(hour, minute):
        return datetime.time(hour, minute)

