                        self.held_symbol, self.entry_price
                    )
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Submitted
            ):
                if orderEvent.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and orderEvent.OrderId == self.exit_ticket.OrderId
            and orderEvent.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self.held_symbol))
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.held_expiry = None
            self.expiration_exit_submitted = False
            self.time_stop_submitted = False

        order_type = getattr(orderEvent, "OrderType", None)
        exercise_type = getattr(OrderType, "OptionExercise", None)
        assignment_type = getattr(OrderType, "OptionAssignment", None)

        if (
            (exercise_type is not None and order_type == exercise_type)
            or (assignment_type is not None and order_type == assignment_type)
            or "assignment" in str(order_type).lower()
            or "exercise" in str(order_type).lower()
        ):
            self.no_entry_today = True
            self.Debug("Unexpected option exercise or assignment processed")

    def OnAssignmentOrderEvent(self, assignmentEvent):
        self.no_entry_today = True
        self.Debug("Unexpected option assignment received")

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0 and not self.equity_liquidation_submitted:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Assignment liquidation"
            )
            self.equity_liquidation_submitted = True

