                    previous_trading_day = self._previous_trading_day(expiry_date)

                    if (
                        self.Time.date() == previous_trading_day
                        and self.Time.time() >= time(15, 45)
                    ):
                        self._submit_exit("expiration time stop")
                    else:
                        self._evaluate_profit_target(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        completed_bar = self._update_five_minute_bar(bar)
        if completed_bar is None:
            return

        self._evaluate_crossover(completed_bar, slice)

    def _update_five_minute_bar(self, bar):
        local_time = self.Time
        if local_time.date() != self._last_minute.date() if self._last_minute else True:
            self._bucket_end = None
            self._bucket_bars = []
            self._last_minute = None

        if local_time.time() < time(9, 30) or local_time.time() > time(16, 0):
            return None

        minute = local_time.replace(second=0, microsecond=0)
        minute_number = minute.hour * 60 + minute.minute

        if minute_number <= 570:
            boundary_minutes = 575
        else:
            boundary_minutes = 570 + ((minute_number - 570 + 4) // 5) * 5

        bucket_end = minute.replace(
            hour=boundary_minutes // 60,
            minute=boundary_minutes % 60
        )

        completed = None

        if self._bucket_end is not None and bucket_end != self._bucket_end:
            if len(self._bucket_bars) == 5:
                completed = self._make_consolidated_bar(self._bucket_bars)

