from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SPYOptionCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=21)
        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.blocked_date = None
        self.current_slice = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = []
        self.bucket_valid = True
        self.last_minute = None

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        # Handle unexpected exercise or assignment into SPY shares.
        equity_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if equity_quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment; "
                f"liquidating {equity_quantity} shares."
            )
            self.MarketOrder(
                self.spy.Symbol,
                -equity_quantity,
                tag="Unexpected exercise or assignment"
            )
            self.blocked_date = today

        # Never intentionally carry an option into its expiration date.
        if (
            self.held_option is not None
            and self.held_option.Expiry.date() <= today
        ):
            self.Debug(
                f"{self.Time}: Expiration safeguard exit for "
                f"{self.held_option.Symbol}."
            )
            self._submit_exit("Expiration safeguard")
            self.blocked_date = today

        # Evaluate exits on every minute Slice.
        if self.held_option is not None:
            if (
                self.time_stop_date == today
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("Time stop")
            else:
                contract = self._get_held_contract(slice)
                if contract is not None:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    if (
                        bid is not None
                        and ask is not None
                        and bid > 0
                        and ask > 0
                        and self.entry_price is not None
                    ):
                        midpoint = (bid + ask) / 2.0
                        if midpoint >= 1.50 * self.entry_price:
                            self._submit_exit("50% profit target")

        # Consolidate the current SPY minute bar.
        if slice.Bars.ContainsKey(self.spy.Symbol):
            self._accept_minute_bar(slice.Bars[self.spy.Symbol])

    def _accept_minute_bar(self, bar: TradeBar):
        minute = bar.Time.replace(second=0, microsecond=0)
        local_date = minute.date()

        if local_date != self.bucket_date:
            self._reset_bucket(local_date)

        if minute.time() < time(9, 30) or minute.time() >= time(16, 0):
            return

        minutes_from_open = (
            minute.hour * 60 + minute.minute
        ) - (9 * 60 + 30)

        if minutes_from_open < 0:
            return

        bucket_index = minutes_from_open // 5
        bucket_start = minute.replace(
            hour=9, minute=30, second=0, microsecond=0
        ) + timedelta(minutes=bucket_index * 5)

        if self.bucket_start != bucket_start:
            self._reset_bucket(local_date)
            self.bucket_start = bucket_start
            self.bucket_valid = True
            self.bucket_bars = []

        if self.last_minute is not None and minute != self.last_minute + timedelta(minutes=1):
            self.bucket_valid = False

        if minute < bucket_start or minute >= bucket_start + timedelta(minutes=5):
            self.bucket_valid = False

        self.bucket_bars.append(bar)
        self.last_minute = minute

        if len(self.bucket_bars) == 5:
            if self.bucket_valid:
                self._on_five_minute_close(
                    bucket_start + timedelta(minutes=5),
                    self.bucket_bars[-1].Close
                )

    def _on_five_minute_close(self, end_time, close):
        self.fast_values.append(close)

        if len(self.fast_values) < 21:
            return

        values = list(self.fast_values)
        current_fast = sum(values[-5:]) / 5.0
        current_slow = sum(values[-20:]) / 20.0
        previous_fast = sum(values[-6:-1]) / 5.0
        previous_slow = sum(values[-21:-1]) / 20.0

        eligible = time(9, 45) <= end_time.time() <= time(14, 30)
        crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible and crossover:
            self._try_enter()

    def _try_enter(self):
        today = self.Time.date()

        if (
            self.blocked_date == today
            or self.entry_order_id is not None
            or self.exit_order_id is not None
            or self.held_option is not None
        ):
            return

